/* Sized for a 1080p panel viewed from a sofa: large type, heavy focus states,
 * and a safe-area inset because TV panels overscan. */

* { margin: 0; padding: 0; box-sizing: border-box; }

body {
    width: 1920px; height: 1080px;
    background: #0f1419;
    color: #e8eaed;
    font-family: "Noto Sans CJK SC", "Malgun Gothic", sans-serif;
    overflow: hidden;
}

.hidden { display: none !important; }
/* #shell behind the player: laid out but not painted. display:none made 返回
 * pay for laying the whole browse screen out again before the first frame —
 * 70–120 ms on this set (10-22, the 顶栏 step of perf: 返回到网格). Anything that
 * asks "can the viewer see this" has to treat it as hidden: nav.js, browseHidden(). */
#shell.veiled { visibility: hidden; }

#video-stage { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; background: #000; }
#avplayer { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; }
#html5-video { position: absolute; left: 0; top: 0; background: #000; }

#shell { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; }

/* ---------------- top bar ---------------- */

#topbar {
    display: flex; align-items: center;
    padding: 32px 64px 20px;
    height: 116px;
}

.brand {
    font-size: 40px; font-weight: 700; letter-spacing: -0.5px;
    color: #ff6699;
    margin-right: 56px;
}

/* Ten tabs at the original 28px/32px measured 1516px, which left the row
 * fighting the account chip for the last 150 pixels of a 1920 panel. Measured
 * again at 26/20/10: 1174px, and the chip has room. */
#tabs { display: flex; gap: 10px; flex: 1; }
/* 2026-10-18: 直播 and the zones chosen in 设置 made the row wider than the
 * bar. It now scrolls sideways under the focus (nav.js, "hscroll") instead of
 * squeezing: min-width 0 lets the flex box be narrower than its tabs, and the
 * tabs keep their size. */
#tabs { min-width: 0; overflow: hidden; }
#tabs .tab { flex-shrink: 0; white-space: nowrap; }

.tab {
    font-size: 26px;
    padding: 12px 20px;
    border-radius: 999px;
    color: #9aa4ad;
    border: 3px solid transparent;
}
.tab.active { color: #e8eaed; background: rgba(255,255,255,0.08); }
.tab.focused { border-color: #ff6699; color: #fff; background: rgba(255,102,153,0.16); }

#status { font-size: 22px; color: #6b7680; }

/* Who the set is signed in as. Sized to the top bar's 64px of content height. */
#account {
    display: flex; align-items: center; gap: 14px;
    padding: 4px 24px 4px 4px;
    margin-right: 28px;
    border-radius: 999px;
    border: 3px solid transparent;
    max-width: 360px;
}
#account.focused { border-color: #ff6699; background: rgba(255,102,153,0.16); }
#account.warn #account-name { color: #ffb454; }

#account-face, #account-initial {
    width: 52px; height: 52px; border-radius: 50%;
    flex: 0 0 auto;
}
#account-face { object-fit: cover; }
#account-initial {
    background: #2a3540; color: #cbd3da;
    font-size: 26px; line-height: 52px; text-align: center;
}
#account-name {
    font-size: 24px; color: #9aa4ad;
    overflow: hidden; white-space: nowrap; text-overflow: ellipsis;
}

/* ---------------- grid ---------------- */

#screen {
    position: absolute; top: 116px; left: 0;
    width: 1920px; height: 964px;
    overflow-y: auto; overflow-x: hidden;
    padding: 8px 64px 64px;
}
#screen::-webkit-scrollbar { display: none; }

/* Three 576px columns and two 32px gaps exactly fill the 1792px
 * content width, so the row has no ragged margin on the right.
 *
 * It was four columns until 2026-09-16: at 427px a thumbnail is 403 pixels
 * wide on a 65" panel, and from the sofa the title under it was a grey smear.
 * Three is one card wider than a phone grid and a third bigger everywhere —
 * picture, title and byline all scale with the column, or the extra width goes
 * to the picture alone and the text stays just as unreadable.
 *
 * Which is a fact about that sofa and that panel, so since 2026-10-18 it is a
 * setting (设置 → 每行视频): body.density-4 and body.density-5 below, PR #2's
 * sizes, for a closer seat or a smaller screen. All three fill the 1792px. */
.grid { display: flex; flex-wrap: wrap; gap: 32px; }

.card {
    position: relative;
    width: 576px;
    border-radius: 12px;
    border: 4px solid transparent;
    padding: 8px;
    transition: transform 0.12s ease;
}
.card.focused {
    border-color: #ff6699;
    background: rgba(255,102,153,0.10);
    transform: scale(1.04);
}

.thumb { position: relative; width: 100%; height: 324px; border-radius: 8px; overflow: hidden; background: #1c2530; }
.thumb img { width: 100%; height: 100%; object-fit: cover; }
.dur {
    position: absolute; right: 8px; bottom: 8px;
    background: rgba(0,0,0,0.75); color: #fff;
    font-size: 24px; padding: 2px 12px; border-radius: 4px;
}

/* Two lines, and the height is the clamp written out: 30 x 1.35 x 2 = 81. A
   card whose title is one line has to stand as tall as its neighbour with two,
   or every row develops a ragged baseline. */
.card-title {
    margin-top: 12px; font-size: 30px; line-height: 1.35;
    height: 81px; overflow: hidden;
}
/* Uploader, views and the publication date on one line. The date sits right;
 * when space runs short the name is what gets an ellipsis (fitCardMeta shaves
 * the date and the count first at four across). */
.card-info {
    display: flex; align-items: center; gap: 6px;
    margin-top: 6px; height: 32px; color: #8b959e;
    white-space: nowrap; font-size: 24px;
}
.card-byline { display: flex; align-items: center; gap: 6px; min-width: 0; flex: 0 1 auto; }
.card-author {
    flex: 0 1 auto; min-width: 0; overflow: hidden;
    text-overflow: ellipsis;
}
.card-views { flex: 0 0 auto; }
/* 直播 cards: a red badge where the duration goes, and 关注 for the people
 * this account follows. */
.dur.live-badge { background: #e5484d; }
.card-follow { flex: 0 0 auto; color: #ff6699; }
.card-info-date { flex: 0 0 auto; margin-left: auto; font-size: 22px; }
.card-info .card-part { flex: 0 0 auto; margin-right: 0; }

body.density-4 .grid { gap: 24px; }
body.density-4 .card { width: 430px; }
body.density-4 .card.focused, body.density-5 .card.focused { transform: scale(1.02); }
body.density-4 .thumb { height: 228px; }
body.density-4 .dur, body.density-5 .dur { font-size: 21px; padding: 2px 10px; }
body.density-4 .card-title { margin-top: 8px; font-size: 25px; line-height: 1.25; height: 63px; }
body.density-4 .card-info { margin-top: 4px; height: 24px; font-size: 20px; }
body.density-4 .card-info-date { font-size: 19px; }

body.density-5 .grid { gap: 18px; }
body.density-5 .card { width: 344px; }
body.density-5 .thumb { height: 180px; }
body.density-5 .card-title { margin-top: 8px; font-size: 22px; line-height: 1.25; height: 55px; }
body.density-5 .card-info { display: block; margin-top: 4px; height: 47px; font-size: 18px; }
body.density-5 .card-byline { width: 100%; height: 24px; }
body.density-5 .card-info-date { display: block; width: 100%; margin: 2px 0 0; font-size: 18px; }

.empty { padding: 80px 0; font-size: 30px; color: #6b7680; text-align: center; }

/* ---------------- search ---------------- */

.search-box {
    font-size: 34px; padding: 20px 28px;
    background: #182029; border-radius: 12px;
    margin-bottom: 24px; min-height: 78px;
    color: #e8eaed;
}
.keyboard { margin-bottom: 32px; }
.krow { display: flex; gap: 12px; margin-bottom: 12px; }
.key {
    width: 86px; height: 72px; line-height: 60px;
    text-align: center; font-size: 30px;
    background: #182029; border-radius: 10px;
    border: 3px solid transparent;
}
.key.wide { width: 180px; }
.key.go { background: #ff6699; color: #fff; }
.key.focused { border-color: #ff6699; background: rgba(255,102,153,0.22); }

/* ---------------- detail ---------------- */

.detail-head { display: flex; gap: 36px; margin-bottom: 40px; }
.detail-pic { width: 640px; height: 400px; object-fit: cover; border-radius: 12px; background: #1c2530; }
.detail-info { flex: 1; }
.detail-info h2 { font-size: 42px; line-height: 1.3; margin-bottom: 16px; }
.detail-meta { font-size: 24px; color: #8b959e; margin-bottom: 24px; }
.detail-desc { font-size: 22px; color: #a8b2bb; line-height: 1.6; margin-bottom: 32px; }

.actions { display: flex; gap: 20px; }
.btn {
    font-size: 30px; padding: 18px 56px;
    background: #ff6699; color: #fff;
    border-radius: 10px; border: 4px solid transparent;
}
.btn.focused { border-color: #fff; }

/* The part number on a history card, so "half watched" means something on a
   twenty-four part upload. */
.card-part {
    display: inline-block;
    background: rgba(255,102,153,0.22); color: #ff8fb4;
    border-radius: 5px; padding: 1px 8px; margin-right: 10px;
}

/* 32/20 was spaced for the four-column cards. At three columns a card is 480px
   tall instead of 371, and the same margins stopped reading as rhythm and
   started reading as a gap — two labels' worth of air was pushing the first
   recommendation most of the way off a 1080 panel. Tighter, and asymmetric on
   purpose: the label belongs to the row under it, so most of what is left goes
   above the label rather than below it. */
.section { font-size: 28px; color: #8b959e; margin: 22px 0 12px; }
/* 继续观看 opens the home screen directly under the tab bar, which carries its
   own 20px of padding — the full top margin there is the bar's air counted
   twice. Only ever the first one: every other 分区 label is separating itself
   from the block above it and needs the whole margin. */
#screen > .section:first-child { margin-top: 4px; }
.parts { display: flex; flex-wrap: wrap; gap: 14px; }
.part {
    font-size: 22px; padding: 14px 24px;
    background: #182029; border-radius: 8px;
    border: 3px solid transparent;
    max-width: 440px; overflow: hidden; white-space: nowrap; text-overflow: ellipsis;
}
.part.focused { border-color: #ff6699; }

/* ---------------- player overlay ---------------- */

#playerui {
    position: absolute; left: 0; bottom: 0;
    width: 1920px; padding: 60px 64px 48px;
    background: linear-gradient(to top, rgba(0,0,0,0.92), rgba(0,0,0,0));
}

#panel-actions { margin: 22px 0 6px; }
#panel-actions .btn, #opt-episode-controls .btn { font-size: 24px; padding: 10px 24px; }
/* Done: liked, coined, in a folder — lit the way the web page lights its icons. */
#panel-actions .btn.act.on { color: #ff6699; border-color: rgba(255,102,153,0.55);
    background: rgba(255,102,153,0.12); }
#panel-actions .btn.act.on.focused { border-color: #fff; }
/* 投币's count and 收藏's folders, opened under the buttons in place. */
.act-more { display: flex; flex-wrap: wrap; align-items: center; gap: 14px; margin: 14px 0 6px; }
.act-more .btn { font-size: 22px; padding: 8px 22px; }
.act-more .btn.on { color: #ff6699; border-color: rgba(255,102,153,0.55); }
.act-more .btn.on.focused { border-color: #fff; }
.act-hint { font-size: 22px; color: #8b959e; }
/* Speed, at the end of the button row (2026-10-20). */
.speed-row { display: flex; align-items: center; gap: 12px; margin-left: 8px; }
.speed-chips { display: flex; gap: 10px; }
#panel-actions .opt { font-size: 24px; padding: 8px 18px; }

#video-actions {
    position: absolute; top: 0; right: 0; bottom: 0; left: 0; z-index: 40;
    display: flex; justify-content: center; align-items: center;
    background: rgba(0,0,0,0.78);
}
#video-actions-box {
    width: 1080px; max-height: 900px; overflow-y: auto;
    padding: 38px 46px; border: 3px solid #ff6699; border-radius: 18px;
    background: #172029;
}
.action-title { font-size: 33px; line-height: 1.3; margin-bottom: 18px; }
.action-status { font-size: 23px; color: #a8b2bb; margin: 12px 0 20px; }
.action-row { display: flex; gap: 14px; margin: 14px 0; }
.action-choice {
    flex: 1; min-width: 0; padding: 14px 18px; font-size: 24px;
    background: #263440; border: 3px solid transparent; border-radius: 9px;
}
.action-choice.focused { border-color: #ff6699; background: #593145; }
.action-choice.active { color: #ff8fb4; }
.action-choice.danger { color: #ffb3a8; }
.action-choice.disabled { opacity: 0.45; }
.action-label { font-size: 23px; color: #8b959e; margin-top: 22px; }
.action-error { font-size: 21px; color: #ffb3a8; margin: 12px 0; }
#player-title { font-size: 36px; margin-bottom: 24px; }
#player-bar { display: flex; align-items: center; gap: 24px; }
#player-pos, #player-dur { font-size: 24px; color: #cbd3da; min-width: 110px; }
#player-dur { text-align: right; }
#player-track { flex: 1; height: 8px; background: rgba(255,255,255,0.22); border-radius: 4px; }
#player-fill { height: 8px; width: 0; background: #ff6699; border-radius: 4px; }
#player-hint { margin-top: 20px; font-size: 22px; color: #8b959e; }

/* 直播 banner: the same bottom gradient as #playerui, none of its bar. */
#live-ui {
    position: absolute; left: 0; bottom: 0;
    width: 1920px; padding: 60px 64px 48px;
    background: linear-gradient(to top, rgba(0,0,0,0.92), rgba(0,0,0,0));
}
#live-top { display: flex; align-items: center; gap: 18px; margin-bottom: 12px; }
#live-badge {
    font-size: 22px; font-weight: 700; color: #fff; background: #e5484d;
    padding: 4px 14px; border-radius: 6px;
}
#live-meta { font-size: 24px; color: #cbd3da; }
#live-title { font-size: 36px; }
#live-hint { margin-top: 20px; font-size: 22px; color: #8b959e; }

/* 设置 → 顶栏: the panel's chips. 推荐 / 搜索 / 设置 are shown where they sit
 * but cannot be focused; the one picked up to move wears arrows. */
#bar-chips .opt, #spare-chips .opt { font-size: 26px; padding: 12px 26px; }
#bar-chips .opt.fixed { color: #6b7680; background: rgba(255,255,255,0.05); }
#bar-chips .opt.picked { background: #ff6699; color: #fff; }
#bar-chips .opt.picked::before { content: "◀ "; }
#bar-chips .opt.picked::after { content: " ▶"; }

/* ---------------- toast ---------------- */

/* In the middle of the screen, not along the bottom (2026-10-20: a notice
   down there is easy to miss — the 番剧
   region-lock notice was missed down there). Above the panel and the side views. */
#toast {
    position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%);
    z-index: 60;
    background: rgba(15,20,25,0.94); color: #fff;
    border: 2px solid rgba(255,102,153,0.6);
    font-size: 32px; line-height: 1.45; padding: 28px 56px; border-radius: 14px;
    /* max-content: with left 50% the shrink-to-fit width stopped at 960px, so
       the 1200 below never applied and long notices wrapped early. */
    width: max-content; max-width: 1200px; text-align: center;
}

/* ---------------- login / mine ---------------- */

.login { display: flex; gap: 72px; align-items: center; padding-top: 40px; }
.login-left { flex: 1; }
.login-left h2 { font-size: 44px; margin-bottom: 28px; }
.login-step { font-size: 30px; color: #ff6699; margin-bottom: 24px; }
.login-note { font-size: 22px; color: #8b959e; line-height: 1.7; margin-bottom: 36px; }
.login-right { flex: 0 0 auto; }
.qr { border-radius: 12px; }

.me { margin-bottom: 20px; }
.me-name { font-size: 46px; margin-bottom: 12px; }
.me-sub { font-size: 24px; color: #8b959e; margin-bottom: 28px; }

.library-links { margin: 10px 0 32px; }
.library-head { display: flex; align-items: center; gap: 28px; margin: 12px 0 26px; }
.library-head .me-name { margin-bottom: 0; }
/* Same widths as the cards at each setting, so a folder list lines up with
 * the grid it opens onto. */
.library-grid { display: flex; flex-wrap: wrap; gap: 32px; }
.library-item {
    width: 576px; min-height: 116px; padding: 16px;
    display: flex; align-items: center; gap: 16px;
    background: #182029; border: 4px solid transparent;
    border-radius: 12px;
}
.library-item.focused { border-color: #ff6699; background: rgba(255,102,153,0.16); }
.library-face, .library-symbol {
    width: 72px; height: 72px; flex: 0 0 auto; border-radius: 50%;
    object-fit: cover; background: #2a3540;
}
.library-symbol { line-height: 72px; text-align: center; color: #ff6699; font-size: 32px; }
.library-text { min-width: 0; display: block; }
.library-text strong, .library-text small {
    display: block; overflow: hidden; white-space: nowrap; text-overflow: ellipsis;
}
.library-text strong { font-size: 26px; }
.library-text small { font-size: 20px; color: #9aa4ad; margin-top: 6px; }
.library-more { margin: 28px 0 48px; }
body.density-4 .library-grid { gap: 24px; }
body.density-4 .library-item { width: 430px; }
body.density-5 .library-grid { gap: 18px; }
body.density-5 .library-item { width: 344px; }

/* ---------------- account switcher ---------------- */

/* A wall of faces, which is what a shared television wants: the choice is
   recognisable across a room and reachable in one press. */
.accounts { padding-top: 48px; }
.accounts h2 { font-size: 48px; margin-bottom: 48px; }

.acc-row { display: flex; flex-wrap: wrap; gap: 40px; margin-bottom: 40px; }

.acc {
    width: 220px;
    padding: 20px 12px 12px;
    border-radius: 16px;
    border: 4px solid transparent;
    text-align: center;
}
.acc.focused { border-color: #ff6699; background: rgba(255,102,153,0.12); }

.acc-face {
    width: 148px; height: 148px; margin: 0 auto 20px;
    border-radius: 50%;
    background: #182029;
    overflow: hidden;
}
.acc-face img { width: 148px; height: 148px; object-fit: cover; display: block; }
.acc-initial, .acc-plus {
    display: block; width: 148px; height: 148px;
    line-height: 148px; text-align: center;
    font-size: 64px; color: #cbd3da;
}
.acc-plus { font-size: 76px; color: #8b959e; }
/* The ring marks who is active without needing the label to be read. */
.acc.on .acc-face { box-shadow: inset 0 0 0 5px #ff6699; }

.acc-name {
    font-size: 26px;
    overflow: hidden; white-space: nowrap; text-overflow: ellipsis;
}
/* Reserved whether or not there is a tag, so the tiles stay on one baseline. */
.acc-tag { font-size: 20px; height: 32px; line-height: 32px; color: #ff6699; }
.accounts.managing .acc-tag { color: #ff7a6b; }

.acc-confirm {
    font-size: 26px; color: #cbd3da; line-height: 1.6;
    margin-bottom: 24px; max-width: 1000px;
}
.acc-note { font-size: 22px; color: #6b7680; }

.btn.ghost { background: transparent; color: #cbd3da; border-color: #33404b; }
.btn.ghost.focused { border-color: #fff; color: #fff; }
.btn.danger { background: #c0392b; }

/* progress sliver on a card whose video was started but not finished */
.seen {
    position: absolute; left: 0; bottom: 0; height: 6px;
    background: #ff6699;
}

/* The system IME attaches to a focused input, but it will not offer candidates
   for one parked off screen — it has nowhere to anchor the candidate strip. So
   the field is shown for real, centred, while it has focus. */
#ime-wrap {
    position: absolute; left: 0; top: 0; width: 1920px; height: 1080px;
    background: rgba(0,0,0,0.82);
    display: flex; flex-direction: column; align-items: center; justify-content: center;
    gap: 24px;
}
#ime {
    width: 1100px; height: 92px; font-size: 40px;
    padding: 0 28px; border-radius: 12px;
    border: 4px solid #ff6699; background: #182029; color: #fff;
}
#ime-hint { font-size: 24px; color: #9aa4ad; }

.suggests { display: flex; flex-wrap: wrap; gap: 14px; margin-bottom: 28px; }
.suggest {
    font-size: 24px; padding: 12px 24px;
    background: #182029; border-radius: 999px;
    border: 3px solid transparent;
}
.suggest.focused { border-color: #ff6699; background: rgba(255,102,153,0.18); }
/* 最近搜过 / 热搜: a label on its own line above each group of chips. */
.suggest-label { width: 100%; font-size: 24px; color: #8b959e; margin-top: 6px; }
.suggest.clear { color: #8b959e; }

/* end-of-video continuation card */
/* The whole screen, not a strip along the bottom: the video is over, so there
   is nothing left to avoid covering, and what replaces it is a choice — the
   queued video in the middle, everything else under it. */
#nextup {
    position: absolute; left: 0; top: 0; width: 1920px; height: 1080px;
    padding: 48px 64px;
    background: rgba(6,9,12,0.95);
    display: flex; flex-direction: column; align-items: center; justify-content: center;
    overflow-y: hidden;
}
#nextup::-webkit-scrollbar { display: none; }
/* With a grid under it there is more than a screenful, and the column has to
   stop centring before it can scroll: a flex column that both centres and
   overflows puts its first rows above scrollTop 0, where nothing can reach
   them. Top-aligned the sums still work out — the queued card, the hint and
   the whole first row fit above the fold, with the second row showing just
   enough of itself to say there is more down there. */
#nextup.has-more { justify-content: flex-start; overflow-y: auto; }
.nextup-main, .nextup-more { flex-shrink: 0; }
.nextup-main { text-align: center; }
.nextup-label { font-size: 24px; color: #ff6699; margin-bottom: 16px; letter-spacing: 2px; }
.nextup-card {
    display: inline-block; max-width: 960px;
    padding: 12px; border-radius: 14px; border: 4px solid transparent;
}
.nextup-card.focused {
    border-color: #ff6699; background: rgba(255,102,153,0.10);
}
.nextup-title { font-size: 40px; line-height: 1.3; margin-top: 18px; }
/* The queued card and the uploader chip side by side, both vertically centred
   so 右键 from the card scores the chip as the same lane (nav.js overlaps
   boxes across the axis of travel) and 下键 still falls to the grid, whose
   cards span the width under both. */
.nextup-row { display: flex; align-items: center; justify-content: center; gap: 48px; }
.nextup-up {
    display: flex; flex-direction: column; align-items: center; gap: 12px;
    width: 300px; padding: 24px 16px; border-radius: 14px;
    border: 4px solid transparent; background: rgba(255,255,255,0.06);
}
.nextup-up.focused { border-color: #ff6699; background: rgba(255,102,153,0.10); }
.nextup-up .up-face, .nextup-up .up-initial { width: 112px; height: 112px; line-height: 112px; font-size: 48px; }
.nextup-up-name { font-size: 32px; font-weight: 700; margin-top: 6px; max-width: 260px; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
.nextup-up-sub { font-size: 22px; color: #9aa4ad; }
.nextup-hint { font-size: 24px; color: #9aa4ad; margin-top: 20px; }
#nextup-count { color: #fff; font-size: 30px; }
/* The same cards the browse grid uses, three to a row, as many rows as the
   related list has to give. The bottom padding is the same trick #options
   uses: without it the last row sits flush against the edge and reads as a
   list that was cut off rather than one that ended. */
.nextup-more { width: 1792px; margin-top: 32px; padding-bottom: 56px; }
.nextup-more .section { margin: 0 0 14px; }

/* ---------------- player, second pass ---------------- */

/* Buffered range behind the played range, the way every video player shows it —
   without it there is no way to tell "still loading" from "stuck". */
#player-track { position: relative; }
#player-buffer {
    position: absolute; left: 0; top: 0; height: 8px; width: 0;
    background: rgba(255,255,255,0.38); border-radius: 4px;
}
#player-fill { position: absolute; left: 0; top: 0; }

/* The scrub head sits above the bar while choosing a position, and the target
   time replaces the elapsed time until it is committed. */
#player-scrub {
    position: absolute; top: -8px; width: 6px; height: 24px;
    background: #fff; border-radius: 3px;
    box-shadow: 0 0 0 4px rgba(255,102,153,0.55);
}
#playerui.scrubbing #player-pos { color: #fff; font-size: 30px; }

/* Chapter marks sit above the fill so they stay visible on the played side. */
#player-chapters { position: absolute; left: 0; top: 0; height: 8px; width: 100%; }
#player-chapters .tick {
    position: absolute; top: -3px; width: 3px; height: 14px;
    margin-left: -1px; background: rgba(255,255,255,0.9); border-radius: 2px;
}

/* The preview hangs above the bar, centred on the head and clamped to the
 * track by app.js — a thumbnail half off the screen is worse than none. */
#scrub-preview { position: absolute; bottom: 30px; width: 384px; margin-left: -192px; }
#scrub-thumb {
    width: 384px; height: 216px; border-radius: 10px;
    background: #000 no-repeat; background-size: cover;
    border: 3px solid rgba(255,255,255,0.92);
    box-shadow: 0 10px 34px rgba(0,0,0,0.75);
}
#scrub-chapter {
    margin-top: 10px; font-size: 22px; color: #fff; text-align: center;
    text-shadow: 0 2px 8px #000;
    overflow: hidden; white-space: nowrap; text-overflow: ellipsis;
}

#player-part { font-size: 24px; color: #ff6699; margin-bottom: 10px; letter-spacing: 1px; }

/* A paused video should look paused from across the room. */
#pause-glyph {
    position: absolute; left: 50%; top: 50%;
    transform: translate(-50%, -50%);
    display: flex; gap: 18px;
    opacity: 0.85;
}
#pause-glyph .bar {
    width: 26px; height: 96px; background: #fff; border-radius: 6px;
    box-shadow: 0 4px 24px rgba(0,0,0,0.6);
}

/* DOM captions work over both the native AVPlay plane and the MSE video. */
#subtitle-overlay { position: absolute; left: 0; top: 0; width: 1920px;
    height: 1080px; padding: 0 100px 182px; display: flex;
    align-items: flex-end; justify-content: center; pointer-events: none; }
#subtitle-text { max-width: 1500px; text-align: center; white-space: pre-line;
    font-size: 42px; line-height: 1.35; color: #fff; font-weight: 600;
    text-shadow: 0 2px 5px #000, 0 0 12px #000, 0 0 22px #000; }
.comments-open #subtitle-overlay { left: 48px; top: 72px; width: 1216px;
    height: 684px; padding: 0 38px 34px; }
.comments-open #subtitle-text { font-size: 31px; max-width: 1100px; }

/* Pulled up from the bottom over the still-playing video, the way a television
   player shows "what else" without leaving the video. Scrolls, because related
   videos are the point of it. */
#options {
    position: absolute; left: 0; top: 46%; width: 1920px; height: 54%;
    padding: 44px 64px 56px;
    overflow-y: auto; overflow-x: hidden;
    background: linear-gradient(to top, rgba(0,0,0,0.97) 30%, rgba(0,0,0,0.55));
}
#options::-webkit-scrollbar { display: none; }

/* Comments share the screen with the playing hardware or MSE video plane. */
#comments-view { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px;
    background: transparent; }
.comments-open #player-loading { left: 48px; top: 72px; width: 1216px; height: 684px; }
.comments-open #loading-title { max-width: 1080px; }
.comments-open #pause-glyph { left: 656px; top: 414px; }
#comments-video-meta { position: absolute; left: 48px; top: 814px; width: 1220px; }
#comments-video-title { font-size: 34px; font-weight: 700; line-height: 1.35;
    max-height: 92px; overflow: hidden; }
#comments-video-hint { color: #9ba3ac; font-size: 23px; margin-top: 18px; }
#comments-pane { position: absolute; left: 1300px; top: 0; width: 620px;
    height: 1080px; padding: 50px 42px 45px 36px; background: #17191f;
    border-left: 2px solid #343841; display: flex; flex-direction: column; }
#comments-head { display: flex; align-items: baseline; justify-content: space-between;
    margin-bottom: 12px; }
#comments-title { font-size: 39px; font-weight: 700; }
#comments-level { font-size: 22px; color: #a5acb6; }
#comments-hint { color: #a5acb6; font-size: 21px; line-height: 1.4;
    margin-bottom: 20px; }
#comments-list { flex: 1; overflow-y: auto; overflow-x: hidden; }
#comments-list::-webkit-scrollbar { width: 5px; }
#comments-list::-webkit-scrollbar-thumb { background: #575f6d; }
#comments-status { min-height: 34px; color: #aab2bc; font-size: 21px; padding-top: 12px; }
.comment-item { border: 2px solid transparent; border-radius: 12px; padding: 18px;
    margin: 0 0 13px; background: #22262e; }
.comment-item.focused { border-color: #ff69a1; background: #34303b; }
.comment-author { font-size: 23px; font-weight: 700; color: #fff; overflow: hidden;
    text-overflow: ellipsis; white-space: nowrap; }
.comment-date { color: #a3aab4; font-size: 18px; margin-top: 3px; }
.comment-text { font-size: 25px; line-height: 1.48; white-space: pre-wrap;
    word-break: break-word; margin: 12px 0; }
.comment-foot { color: #b4bbc5; font-size: 21px; }
.comment-liked { color: #ff80ab; }
.comment-replies { float: right; color: #ffb2cc; }

#panel-head { margin-bottom: 32px; }
#panel-title { font-size: 38px; line-height: 1.3; margin-bottom: 10px; }
#panel-meta { font-size: 23px; color: #8b959e; margin-bottom: 14px; display: flex; align-items: center; gap: 22px; }
/* The uploader's name as a chip: the one thing in the panel head that can be
   pressed, so it has to look pressable next to two spans of grey. The ring is
   the same pink as every other focus state; the resting look borrows from .opt
   so the panel reads as one family of buttons. */
.opt-up {
    font-size: 24px; padding: 8px 22px; border-radius: 999px;
    background: rgba(255,255,255,0.10); color: #e8eaed;
    border: 3px solid transparent;
}
.opt-up::before { content: "UP "; color: #ff6699; font-weight: 700; }
.opt-up.focused { border-color: #ff6699; background: rgba(255,102,153,0.18); }
.panel-meta-rest { white-space: nowrap; }
/* 关注 (2026-10-20), beside the uploader's chip and on their page. */
/* The uploader chip's own light grey, not pink (pink was too bright);
   「已关注」 in dimmer text. */
.opt-follow {
    font-size: 24px; padding: 8px 22px; border-radius: 999px;
    background: rgba(255,255,255,0.10); color: #e8eaed; border: 3px solid transparent;
}
.opt-follow.on { color: #8b959e; }
.opt-follow.focused { border-color: #ff6699; background: rgba(255,102,153,0.18); }
.up-head .opt-follow { font-size: 26px; padding: 10px 30px; margin-left: 12px; }

/* ---------------- uploader page ---------------- */

/* Above the grid, not focusable. Same 1792px content width as the cards, so
   the avatar lines up with the first column's left edge. */
.up-head {
    display: flex; align-items: center; gap: 24px;
    margin: 4px 0 22px;
}
.up-face, .up-initial {
    width: 88px; height: 88px; border-radius: 50%; flex: 0 0 auto;
    object-fit: cover; background: #2a3540;
}
.up-initial {
    display: inline-block; color: #cbd3da; text-align: center;
    font-size: 40px; line-height: 88px;
}
.up-name { font-size: 40px; font-weight: 700; }
.up-sub { font-size: 26px; font-weight: 400; color: #8b959e; margin-left: 18px; }
#panel-desc { font-size: 22px; color: #a8b2bb; line-height: 1.6; max-width: 1500px; }
.opt-group { margin-bottom: 32px; }
.opt-label { font-size: 24px; color: #8b959e; margin-bottom: 16px; letter-spacing: 2px; }
.opt-row { display: flex; flex-wrap: wrap; gap: 16px; }
/* Sized to its own text rather than to a column, so the row degrades on its
   own: bare numbers pack five or six to a line the way they always did, and
   named parts take the width they need up to a limit and then ellipsis. One
   rule, no branch on "does this upload name its parts" — and nav.js walks a
   ragged row by design, so nothing has to be told how many fit. */
.opt {
    font-size: 28px; padding: 14px 34px;
    background: rgba(255,255,255,0.10); border-radius: 10px;
    border: 3px solid transparent; color: #e8eaed;
    max-width: 560px; flex-shrink: 0; overflow: hidden;
    display: flex; align-items: baseline; gap: 16px;
}
/* Three parts to a chip, and only the middle one may be cut: the number is the
   address, the name is the answer, the length is what decides between two
   episodes that both sound right. Truncation lives on the name because it is
   the only one that can be long — `min-width: 0` because a flex item refuses
   to shrink below its content otherwise, which is what silently turns
   text-overflow into no truncation at all. */
.opt-p { color: #8b959e; flex-shrink: 0; }
.opt-name { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.opt-dur { color: #8b959e; font-size: 24px; flex-shrink: 0; margin-left: auto; }
.opt.current { background: rgba(255,102,153,0.24); color: #fff; }
/* 分P and 合集 as one row that slides sideways under the focus (nav.js
 * "hscroll"), 2026-10-18. Wrapped, a season of a hundred-odd episodes was
 * twenty-odd lines, and getting from the related videos back up to the
 * uploader took that many presses of 上 — the selftest ran out at 24. */
.opt-row.hscroll { flex-wrap: nowrap; overflow: hidden; }
/* ⟶ 2026-10-20 the 合集 went back to tiles, four to a row (tiles read more
 * plainly than one sideways row): 4 × 436 + 3 × 16 = 1792. 分P followed
 * the same evening, folded into ranges like the 合集. */
#opt-season .opt, #opt-parts .opt { width: 436px; max-width: none; }
/* Past 50 the 合集 — and since the same evening 分P — is a row of ranges
   instead (openEpisodeList). */
#opt-season .opt.opt-range, #opt-parts .opt.opt-range { width: auto; }
/* The range's episodes, in the comments' pane: number, the whole title (two
   lines at most), length; the playing one in pink. */
.ep-item { display: flex; align-items: baseline; gap: 16px; font-size: 25px; }
.ep-no { color: #8b959e; flex-shrink: 0; min-width: 48px; }
.ep-title { flex: 1; min-width: 0; line-height: 1.4; overflow: hidden;
    display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }
.ep-dur { color: #8b959e; font-size: 21px; flex-shrink: 0; }
.ep-item.current .ep-no, .ep-item.current .ep-title { color: #ff6699; }
.opt.current .opt-p, .opt.current .opt-dur { color: rgba(255,255,255,0.8); }
.opt.focused { border-color: #ff6699; }

#player-quality {
    font-size: 22px; color: #0f1419; background: #cbd3da;
    padding: 4px 14px; border-radius: 6px; margin-left: 8px;
}

/* Titles were clipped mid-line with a hard edge, which reads as a rendering
   fault rather than as truncation. */
.card-title {
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    text-overflow: ellipsis;
}

/* Once results exist the keyboard steps aside rather than pushing them off
   the bottom of the screen. */
/* Collapsed after a search: the letter rows fold away so the results are not
 * buried under four rows of keys, but the action row (中文输入 / 空格 / 删除 /
 * 搜索) stays — display:none on the whole keyboard made it unreachable, and
 * once collapsed nothing could ever uncollapse it (2026-09-07). */
.keyboard.collapsed .krow:not(.acts) { display: none; }

#nextup-thumb {
    display: block; margin: 0 auto;
    width: 480px; height: 270px; object-fit: cover;
    border-radius: 10px; background: #1c2530;
}

/* A hint that the panel continues below the fold. */
#options::after {
    content: ""; display: block; height: 40px;
}

/* Between the button press and the first frame the screen was simply black,
   which reads as a crash rather than as loading. */
#player-loading {
    position: absolute; left: 0; top: 0; width: 1920px; height: 1080px;
    display: flex; flex-direction: column; align-items: center; justify-content: center;
    gap: 32px; background: #0f1419;
}
/* With the panel up — 返回 from a related pick opens it before the video has
   loaded — the spinner belongs to the strip above it, not behind it. */
.options-open #player-loading { height: 46%; }
#loading-title { font-size: 30px; color: #9aa4ad; max-width: 1200px; text-align: center; }
/* The self-rescue heartbeat. Empty (and invisible) in the normal case; the
   ladder writes here while it works so a long recovery cannot be mistaken
   for a crash. */
#loading-status { font-size: 24px; color: #6b7680; min-height: 30px; text-align: center; }
.spinner {
    width: 72px; height: 72px; border-radius: 50%;
    border: 6px solid rgba(255,255,255,0.18);
    border-top-color: #ff6699;
    animation: spin 0.9s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }

/* 弹幕 (danmaku.js, 2026-10-18). The top ~70% of the picture — the bottom is
 * the subtitles' and the progress bar's. 设置 can narrow it to the top quarter
 * or open it to the whole picture (PR #10, 10-25). No z-index: document order puts it
 * under the subtitles and the player chrome. Plain text-shadow for the outline;
 * CSS filters were measured expensive on this set (douyin-tizen).
 *
 * The opacity sits on each comment, not on the box, and the outline has no
 * blur (deploy.sh --dmperf on the set, 10-18): opacity on the 1920×756 box
 * draws the whole box off screen every frame, and a blurred shadow is slow to
 * raster each time a comment enters. Together they cost 12 frames in 14 s at
 * the median (73 at worst) — the shake the viewer saw — against 2 without. */
#danmaku { position: absolute; left: 0; top: 0; width: 1920px; height: 756px;
    overflow: hidden; pointer-events: none; }
#danmaku.dm-area-top { height: 270px; }
#danmaku.dm-area-upper { height: 756px; }
#danmaku.dm-area-full { height: 1080px; }
#danmaku .dm { position: absolute; left: 0; top: 0; white-space: nowrap;
    font-weight: 600; line-height: 1.24; will-change: transform; opacity: 0.85;
    text-shadow: 1px 1px 0 #000, -1px -1px 0 #000, 1px -1px 0 #000, -1px 1px 0 #000; }
.comments-open #danmaku { display: none; }
/* The play panel starts at 46% (496px). Without this the comments drifted on
 * behind its rows and over the speed chips (seen in the 10-18 README shots).
 * The renderer reads the height and only sends new comments down the rows
 * still in view; the ones crossing a hidden row are clipped until it closes. */
.options-open #danmaku { height: 496px; }
.options-open #danmaku.dm-area-top { height: 270px; }

files.css/legacy-layout.css:
/* Conditional fallback for Chromium 69 (2020/Tizen 5.5). The modern layout is
 * untouched on engines that implement flex gap. All selectors are also valid
 * in Chromium 69. Margins replace flex gap; grid-gap keeps the exact card grid.
 *
 * From PR #2 (skywalker-lili, tested on a Q90T), cut to this layout: three
 * 576px columns by default (and the fork's four and five as settings).
 * Every flex container with `gap` in app.css needs its twin here — a new one
 * without it renders with its children touching on these sets.
 */
.legacy-flex-gap #tabs,
.legacy-flex-gap #account,
.legacy-flex-gap .grid,
.legacy-flex-gap .krow,
.legacy-flex-gap .detail-head,
.legacy-flex-gap .actions,
.legacy-flex-gap .parts,
.legacy-flex-gap #player-bar,
.legacy-flex-gap .login,
.legacy-flex-gap .acc-row,
.legacy-flex-gap #ime-wrap,
.legacy-flex-gap .suggests,
.legacy-flex-gap .nextup-row,
.legacy-flex-gap .nextup-up,
.legacy-flex-gap #pause-glyph,
.legacy-flex-gap #panel-meta,
.legacy-flex-gap .up-head,
.legacy-flex-gap .opt-row,
.legacy-flex-gap .opt,
.legacy-flex-gap #player-loading,
.legacy-flex-gap .card-info,
.legacy-flex-gap .card-byline,
.legacy-flex-gap .action-row,
.legacy-flex-gap .library-head,
.legacy-flex-gap .library-grid,
.legacy-flex-gap .library-item,
.legacy-flex-gap #live-top,
.legacy-flex-gap .act-more,
.legacy-flex-gap .speed-row,
.legacy-flex-gap .speed-chips,
.legacy-flex-gap .ep-item { gap: 0; }

.legacy-flex-gap #tabs > :not(.hidden) ~ :not(.hidden) { margin-left: 10px; }
.legacy-flex-gap #account > :not(.hidden) ~ :not(.hidden) { margin-left: 14px; }
.legacy-flex-gap .krow > * + * { margin-left: 12px; }
.legacy-flex-gap .detail-head > * + * { margin-left: 36px; }
.legacy-flex-gap .actions > * + * { margin-left: 20px; }
.legacy-flex-gap #player-bar > :not(.hidden) ~ :not(.hidden) { margin-left: 24px; }
.legacy-flex-gap .login > * + * { margin-left: 72px; }
.legacy-flex-gap .nextup-row > * + * { margin-left: 48px; }
.legacy-flex-gap #pause-glyph > * + * { margin-left: 18px; }
.legacy-flex-gap #live-top > * + * { margin-left: 18px; }
.legacy-flex-gap #panel-meta > * + * { margin-left: 22px; }
.legacy-flex-gap .up-head > * + * { margin-left: 24px; }
.legacy-flex-gap .opt > .opt-name { margin-left: 16px; }
/* Preserve the original auto margin that right-aligns the part duration. */
.legacy-flex-gap .opt > .opt-dur { margin-left: auto; padding-left: 16px; }

/* .grid is flex-wrap with gap around fixed-width cards (border-box), so fixed
 * tracks with the same gap reproduce it exactly — one set per cards-per-row
 * setting. The folder and following lists use the same widths. */
.legacy-flex-gap .grid,
.legacy-flex-gap .library-grid {
    display: grid;
    grid-template-columns: repeat(3, 576px);
    grid-gap: 32px;
}
.legacy-flex-gap body.density-4 .grid,
.legacy-flex-gap body.density-4 .library-grid {
    grid-template-columns: repeat(4, 430px);
    grid-gap: 24px;
}
.legacy-flex-gap body.density-5 .grid,
.legacy-flex-gap body.density-5 .library-grid {
    grid-template-columns: repeat(5, 344px);
    grid-gap: 18px;
}

.legacy-flex-gap .card-info .card-part { margin-right: 6px; }
.legacy-flex-gap .card-views { margin-left: 6px; }
.legacy-flex-gap .action-row > * + * { margin-left: 14px; }
.legacy-flex-gap .library-head > * + * { margin-left: 28px; }
.legacy-flex-gap .library-item .library-text { margin-left: 16px; }

/* A trailing child margin plus an equal negative container margin reproduces
 * the available wrap width. Compensate the original bottom margins separately.
 */
.legacy-flex-gap .parts { margin-right: -14px; margin-bottom: -14px; }
.legacy-flex-gap .parts > * { margin-right: 14px; margin-bottom: 14px; }
.legacy-flex-gap .suggests { margin-right: -14px; margin-bottom: 14px; }
.legacy-flex-gap .suggests > * { margin-right: 14px; margin-bottom: 14px; }
.legacy-flex-gap .suggests > .suggest-label { width: calc(100% - 14px); }
.legacy-flex-gap .acc-row { margin-right: -40px; margin-bottom: 0; }
.legacy-flex-gap .acc-row > * { margin-right: 40px; margin-bottom: 40px; }
.legacy-flex-gap .speed-row > * + * { margin-left: 12px; }
.legacy-flex-gap .speed-chips > * + * { margin-left: 10px; }
.legacy-flex-gap .ep-item > * + * { margin-left: 16px; }
.legacy-flex-gap .act-more { margin-right: -14px; }
.legacy-flex-gap .act-more > * { margin-right: 14px; margin-bottom: 14px; }
.legacy-flex-gap .opt-row { margin-right: -16px; margin-bottom: -16px; }
.legacy-flex-gap .opt-row > * { margin-right: 16px; margin-bottom: 16px; }

.legacy-flex-gap #ime-wrap > * + * { margin-top: 24px; }
.legacy-flex-gap .nextup-up > * + * { margin-top: 12px; }
.legacy-flex-gap .nextup-up > .nextup-up-name { margin-top: 18px; }
.legacy-flex-gap #player-loading > * + * { margin-top: 32px; }

/* Chromium 56 and older (Tizen 4 and 3, since required_version went to 3.0
 * for issues #4 and #5) have no CSS grid either: the display: grid above is
 * dropped and the card grid is flex with gap 0, cards touching. compat.js adds
 * legacy-no-grid there; margins on the cards and an equal negative margin on
 * the container stand in, the way .parts does. display: flex is what those
 * engines end up with anyway — it is spelled out so adding the class by hand
 * in a modern browser shows exactly this layout; so is gap: 0, because a
 * modern engine reads the grid-gap above as flex gap too, and 56 does not. */
.legacy-no-grid .grid,
.legacy-no-grid .library-grid { display: flex; gap: 0; margin: 0 -32px -32px 0; }
.legacy-no-grid .grid > *,
.legacy-no-grid .library-grid > * { margin: 0 32px 32px 0; }
.legacy-no-grid body.density-4 .grid,
.legacy-no-grid body.density-4 .library-grid { gap: 0; margin: 0 -24px -24px 0; }
.legacy-no-grid body.density-4 .grid > *,
.legacy-no-grid body.density-4 .library-grid > * { margin: 0 24px 24px 0; }
.legacy-no-grid body.density-5 .grid,
.legacy-no-grid body.density-5 .library-grid { gap: 0; margin: 0 -18px -18px 0; }
.legacy-no-grid body.density-5 .grid > *,
.legacy-no-grid body.density-5 .library-grid > * { margin: 0 18px 18px 0; }

