        for (i = 0; i < 64; i += 4) {
            out[i >> 2] = s.charCodeAt(offset + i) +
                (s.charCodeAt(offset + i + 1) << 8) +
                (s.charCodeAt(offset + i + 2) << 16) +
                (s.charCodeAt(offset + i + 3) << 24);
