    }

    function load() {
        if (data) { return data; }
        var raw = null;
        try { raw = localStorage.getItem(KEY); } catch (e) {}
        if (raw) {
            try { data = JSON.parse(raw); } catch (e) { data = null; }
        }
        if (!data || !data.list) {
            data = blank();
            migrate();
            persist();
        }
        return data;
    }

    function get(id) {
        var d = load();
        for (var i = 0; i < d.list.length; i++) {
            if (d.list[i].id === id) { return d.list[i]; }
        }
        return null;
    }

    /* The engine's jar is global, so switching accounts has to empty it or the
     * previous account's cookies ride along on any request that carries
     * credentials. Returns whether it actually happened: the API is not present
     * on every firmware, and a caller that assumes it worked would let two
     * accounts bleed into each other silently. */
    function clearJar() {
        try {
            if (typeof tizen !== "undefined" && tizen.websetting &&
                tizen.websetting.removeAllCookies) {
                tizen.websetting.removeAllCookies();
                return true;
            }
        } catch (e) {}
        return false;
    }

    return {
        GUEST: GUEST,

        all: function () { return load().list; },
        count: function () { return load().list.length; },
        get: get,

        activeId: function () { return load().activeId || GUEST; },
        active: function () {
            var d = load();
            return d.activeId === GUEST ? null : get(d.activeId);
        },

        /* A key that belongs to the person using the set rather than to the set.
         * Callers re-derive it on every access instead of caching it, so that a
         * switch cannot leave a stale namespace behind. */
        scope: function (base) { return base + "@" + (load().activeId || GUEST); },

        /* The one place an account change happens. Everything else reads the
         * active account; nothing else writes it. */
        switchTo: function (id) {
            var d = load();
            if (id !== GUEST && !get(id)) { return null; }
            if (d.activeId === id) { return this.active(); }

            /* Empty the jar before anyone else's request can pick it up. The
             * account that owned it loses it — that is exactly the situation
             * needsRelogin exists to describe. */
            if (clearJar()) { d.jarOwner = null; }

            d.activeId = id;
            var acc = id === GUEST ? null : get(id);
            if (acc) { acc.lastUsedAt = new Date().getTime(); }
            persist();
            return acc;
        },

        /* Credentials in hand. Same person signing in again updates the account
         * they already have rather than growing a second face on the switcher.
         *
         * The mid is the reliable way to recognise them, and the TV path always
         * supplies it. The web fallback supplies nothing, so `intoId` carries
         * the app's intent instead — "this scan is meant to restore that row" —
         * and is honoured only when it cannot be somebody else's row. */
        remember: function (session, profile, intoId) {
            var d = load();
            profile = profile || {};
            var acc = null, i;

            if (profile.mid) {
                for (i = 0; i < d.list.length; i++) {
                    if (d.list[i].mid === profile.mid) { acc = d.list[i]; break; }
                }
            }
            if (!acc && intoId) {
                var target = get(intoId);
                if (target && (!target.mid || !profile.mid || target.mid === profile.mid)) {
                    acc = target;
                }
            }
            if (!acc) { acc = create(); d.list.push(acc); }

            acc.session = session;
            if (profile.mid) { acc.mid = profile.mid; }
            if (profile.uname) { acc.uname = profile.uname; }
            if (profile.face) { acc.face = profile.face; }
            if (profile.level !== undefined && profile.level !== null) {
                acc.level = profile.level;
            }
            acc.lastUsedAt = new Date().getTime();

            d.activeId = acc.id;
            /* A session with no readable SESSDATA lives entirely in the jar, so
             * this account now owns it. One with readable credentials does not
             * care what the jar holds. */
            d.jarOwner = (session && !session.SESSDATA) ? acc.id : d.jarOwner;
            persist();
            return acc;
        },

        /* Display fields learned after the fact, from nav().
         *
         * An account's mid does not change. If nav answers with a different one
         * than the login handed over, the answer is about somebody else — the
         * request did not carry this account's session — and writing it here
         * would rename the row to whoever the server did recognise. That is not
         * hypothetical: it stamped one person's name and mid onto three rows
         * belonging to different logins, and the only visible symptom was a new
         * account showing the previous account's face. Refuse and say so; the
         * caller reports it. */
        describe: function (id, profile) {
            var acc = get(id);
            if (!acc) { return null; }
            if (acc.mid && profile.mid && acc.mid !== profile.mid) { return null; }
            if (profile.mid) { acc.mid = profile.mid; }
            if (profile.uname) { acc.uname = profile.uname; }
            if (profile.face) { acc.face = profile.face; }
            if (profile.level !== undefined && profile.level !== null) {
                acc.level = profile.level;
            }
            persist();
            return acc;
        },

        remove: function (id) {
            var d = load();
            for (var i = 0; i < d.list.length; i++) {
                if (d.list[i].id !== id) { continue; }
                d.list.splice(i, 1);

                /* Take their history with them. Leaving it behind would hand it
                 * to whoever is assigned this id next. */
                for (var j = 0; j < SCOPED.length; j++) {
                    try { localStorage.removeItem(SCOPED[j] + "@" + id); } catch (e) {}
                }
                if (d.jarOwner === id) { clearJar(); d.jarOwner = null; }

                if (d.activeId === id) {
                    /* Fall back to whoever used the set most recently. */
                    var next = GUEST, best = -1;
                    for (var k = 0; k < d.list.length; k++) {
                        if ((d.list[k].lastUsedAt || 0) > best) {
                            best = d.list[k].lastUsedAt || 0;
                            next = d.list[k].id;
                        }
                    }
                    /* Unless the account being promoted is the one the jar
                     * holds — emptying it then would strand the very session
                     * about to be handed the screen. */
                    if (d.jarOwner !== next && clearJar()) { d.jarOwner = null; }
                    d.activeId = next;
                }
                persist();
                return true;
            }
            return false;
        },

        /* True when this account's credentials are gone: they only ever existed
         * in the jar, and the jar has since been emptied or taken over. The UI
         * turns this into "needs a fresh scan" rather than serving a signed-out
         * feed that looks like a broken account. */
        needsRelogin: function (acc) {
            if (!acc || !acc.session) { return true; }
            if (acc.session.SESSDATA) { return false; }
            return load().jarOwner !== acc.id;
        },

        /* Whether a request may let the engine attach the jar. Only when this
         * account is the one the jar holds — otherwise withCredentials would
         * quietly send someone else's session. */
        jarBelongsTo: function (id) { return load().jarOwner === id; },

        /* For the whoami probe only. Which account the jar is believed to hold
         * is a belief this code maintains, never one it can read back, so it is
         * worth saying out loud next to what the server actually answers. */
        jarOwner: function () { return load().jarOwner; },

        /* The exported form forgets the owner as well. The web ticket flow
         * empties the jar before the hop that refills it; if that hop fails or
         * is cancelled, the previous owner would otherwise still be "signed
         * in" over an empty jar — withCredentials on, anonymous feed served
         * under their name, which is the exact state needsRelogin exists to
         * flag. Internal callers (switchTo/remove) already null it themselves. */
        clearJar: function () {
            var ok = clearJar();
            if (ok) { var d = load(); d.jarOwner = null; persist(); }
            return ok;
        }
    };
})();

files.js/auth.js:
/* Signing in, for as many people as share the television.
 *
 * There are two QR flows here and the difference between them is the whole
 * reason multiple accounts are possible at all:
 *
 *   TV login (passport-tv-login) returns the credentials as JSON — SESSDATA,
 *   bili_jct and a refresh token, in the response body. They can be stored,
 *   swapped and replayed as a Cookie header, so any number of accounts can sit
 *   on the set and switching between them is instant.
 *
 *   Web login (passport-login/web) is the fallback. On this account it does not
 *   hand back credentials at all: the poll answers with a cross-domain url whose
 *   query carries only `ticket`, and the session arrives as Set-Cookie on that
 *   hop. XHR cannot read Set-Cookie, so the only way to keep it is to let the
 *   engine's own jar take it — and the jar is global, unreadable, and holds one
 *   account at a time. An account acquired this way cannot be switched away from
 *   and switched back to; Accounts.needsRelogin is how that surfaces.
 *
 * The TV endpoints want a signed request, which is what md5.js is for. That
 * signature identifies this client as bilibili's own television client. It is
 * the only login route the platform offers that returns readable credentials.
 */
var Auth = (function () {
    "use strict";

    /* bilibili's Android TV client. The endpoints below reject an unsigned
     * request and accept no other appkey.
     *
     * ── This is the project's one deliberate trade-off. Read before changing. ──
     *
     * Signing with these makes this client present itself to bilibili as the
     * official television client. The values are not secret — they are公开
     * documented across the bilibili API community — but using them is a
     * decision, not an oversight, and it buys exactly one thing: credentials
     * this code can read, store and replay.
     *
     * `passport-tv-login` answers with SESSDATA, bili_jct, an access token and
     * a refresh token, as JSON. That is what makes several people able to share
     * one television: each account is a value this app holds and can swap.
     *
     * The web QR flow (startWeb below) is the alternative and needs none of
     * this. Its cost is structural, not cosmetic: it finishes by redirecting
     * through a URL whose `Set-Cookie` the engine swallows into its own global
     * jar. XHR never sees the credentials. So an account signed in that way
     * cannot be stored, cannot be restored, and cannot coexist with another —
     * the jar holds one session, and there is no way to put a previous one
     * back.
     *
     * Both paths are implemented and both work. The web flow is the automatic
     * fallback whenever the TV path is unavailable, and it fires *before* any
     * QR code reaches the screen — swapping the code out while somebody is
     * already holding up a phone is worse than failing.
     *
     * To ship without the TV appkey: delete these two constants and make
     * `login()` call `startWeb` directly. Everything keeps working for one
     * account. `Accounts` will still hold a list, but a second sign-in
     * dispossesses the first, and `Accounts.needsRelogin` will start flagging
     * whoever lost the jar. Watch-history reporting back to bilibili also stops
     * — `/x/v2/history/report` accepts `access_key` and rejects `csrf` from
     * this device, so it depends on the TV path.
     *
     * See README「两条登录路径」for the same trade-off in prose. */
    var TV_APPKEY = "4409e2ce8ffd12b8";
    var TV_APPSEC = "59b43e04ad6965f34319062b478f83dd";
    var TV_BASE = "https://passport.bilibili.com/x/passport-tv-login";
    var WEB_BASE = "https://passport.bilibili.com/x/passport-login/web";

    /* Every in-flight login carries the generation it started in. A cancelled or
     * superseded run therefore cannot announce over the live one — the same trap
     * the player hits with AVPlay's listener singleton, and it bit this file
     * once already when an orphaned poller declared a perfectly good code
     * expired. */
    var gen = 0;
    var pollTimer = null;

    /* Set when this login is meant to restore an account already on the set
     * rather than add a new one. Only one login can be in flight — the
     * generation counter sees to that — so it can live here instead of being
     * threaded through every callback. */
    var intoId = null;

    function stop() {
        if (pollTimer) { clearInterval(pollTimer); pollTimer = null; }
    }

    function session() {
        var acc = Accounts.active();
        return (acc && acc.session) || null;
    }

    /* ---------------- signed requests ---------------- */

    function sign(params) {
        params.appkey = TV_APPKEY;
        params.ts = Math.floor(new Date().getTime() / 1000);

        var keys = [], k;
        for (k in params) { if (params.hasOwnProperty(k)) { keys.push(k); } }
        keys.sort();

        var parts = [];
        for (var i = 0; i < keys.length; i++) {
            parts.push(keys[i] + "=" + encodeURIComponent(params[keys[i]]));
        }
        var qs = parts.join("&");
        return qs + "&sign=" + MD5(qs + TV_APPSEC);
    }

    function postForm(url, body, onOk, onFail) {
        var xhr = new XMLHttpRequest();
        var settled = false;
        function fail(why) { if (!settled) { settled = true; onFail(why); } }
        function ok(j) { if (!settled) { settled = true; onOk(j); } }

        xhr.open("POST", url, true);
        xhr.setRequestHeader("Content-Type", "application/x-www-form-urlencoded");
        xhr.timeout = 20000;
        xhr.onreadystatechange = function () {
            if (xhr.readyState !== 4) { return; }
            if (xhr.status !== 200) { fail("HTTP " + xhr.status); return; }
            try { ok(JSON.parse(xhr.responseText)); }
            catch (e) { fail("bad JSON"); }
        };
        xhr.ontimeout = function () { fail("timeout"); };
        xhr.onerror = function () { fail("network error"); };
        xhr.send(body);
    }

    function getJson(url, onOk, onFail) {
        var xhr = new XMLHttpRequest();
        var settled = false;
        function fail(why) { if (!settled) { settled = true; onFail(why); } }
        function ok(j) { if (!settled) { settled = true; onOk(j); } }

        xhr.open("GET", url, true);
        xhr.timeout = 20000;
        xhr.onreadystatechange = function () {
            if (xhr.readyState !== 4) { return; }
            if (xhr.status !== 200) { fail("HTTP " + xhr.status); return; }
            try { ok(JSON.parse(xhr.responseText)); }
            catch (e) { fail("bad JSON"); }
        };
        xhr.ontimeout = function () { fail("timeout"); };
        xhr.onerror = function () { fail("network error"); };
        xhr.send();
    }

    /* ---------------- TV login ---------------- */

    /* The payload has been seen both flat and nested under token_info, so read
     * whichever is present rather than assuming. */
    function sessionFromTv(d) {
        var t = d.token_info || d;
        var out = {
            access_token: t.access_token || "",
            refresh_token: t.refresh_token || "",
            expiresAt: new Date().getTime() + ((t.expires_in || 0) * 1000),
            savedAt: new Date().getTime()
        };
        var cookies = (d.cookie_info && d.cookie_info.cookies) || [];
        for (var i = 0; i < cookies.length; i++) {
            var c = cookies[i] || {};
            if (c.name === "SESSDATA") { out.SESSDATA = c.value; }
            else if (c.name === "bili_jct") { out.bili_jct = c.value; }
            else if (c.name === "DedeUserID") { out.DedeUserID = c.value; }
        }
        /* Without SESSDATA there is nothing to replay, and storing the account
         * anyway would leave isLoggedIn true with no session behind it — which
         * then suppresses every "please sign in" path in the app. */
        if (!out.SESSDATA) { return null; }
        return { session: out, mid: t.mid || Number(out.DedeUserID) || 0 };
    }

    function startTv(mine, onState, onUnavailable) {
        postForm(TV_BASE + "/qrcode/auth_code", sign({ local_id: "0" }), function (r) {
            if (mine !== gen) { return; }
            if (r.code !== 0 || !r.data || !r.data.auth_code) {
                /* The endpoint is there but will not issue a code — nothing the
                 * viewer can act on, so quietly try the other flow. */
                onUnavailable("auth_code " + (r.message || r.code));
                return;
            }
            var code = r.data.auth_code;
            onState({ kind: "qr", url: r.data.url, via: "tv" });

            var announced = 0;
            pollTimer = setInterval(function () {
                if (mine !== gen) { stop(); return; }
                postForm(TV_BASE + "/qrcode/poll",
                         sign({ auth_code: code, local_id: "0" }), function (p) {
                    if (mine !== gen) { return; }

                    if (p.code === 0 && p.data) {
                        var got = sessionFromTv(p.data);
                        if (!got) {
                            stop();
                            onState({ kind: "error", why: "登录返回里没有凭证" });
                            return;
                        }
                        stop();
                        gen++;   /* this run is finished; nothing else may report */
                        /* Whether a row was created is only knowable by counting
                         * across the call: remember() recognises the same person
                         * by mid and takes over their existing row, which is a
                         * different event from adding a face to the switcher and
                         * must not be reported as one. */
                        var had = Accounts.count();
                        var acc = Accounts.remember(got.session, { mid: got.mid }, intoId);
                        var created = Accounts.count() > had;
                        /* The mid bilibili itself attached to this scan, and the
                         * row it landed in. Without both, "the wrong person's
                         * name came up" cannot be split into "the scan gave us
                         * the wrong credentials" and "the right credentials went
                         * to the wrong place". */
                        onState({ kind: "done", via: "tv", mid: got.mid,
                                  accId: acc && acc.id, created: created,
                                  into: intoId });
                        return;
                    }
                    if (p.code === 86038) { stop(); onState({ kind: "expired" }); return; }
                    if (p.code === 86090 && announced !== 86090) {
                        announced = 86090;
                        onState({ kind: "scanned" });
                    }
                    /* 86039 is "not scanned yet", which is not news. */
                }, function () { /* a dropped poll is not fatal; the next retries */ });
            }, 3000);
        }, function (why) { onUnavailable(why); });
    }

    /* ---------------- web login, the fallback ---------------- */

    function startWeb(mine, onState) {
        getJson(WEB_BASE + "/qrcode/generate", function (r) {
            if (mine !== gen) { return; }
            if (r.code !== 0) { onState({ kind: "error", why: r.message || r.code }); return; }

            var key = r.data.qrcode_key;
            onState({ kind: "qr", url: r.data.url, via: "web" });

            var announced = 0;
            pollTimer = setInterval(function () {
                if (mine !== gen) { stop(); return; }
                getJson(WEB_BASE + "/qrcode/poll?qrcode_key=" + key, function (p) {
                    if (mine !== gen) { return; }
                    var d = p.data || {};

                    if (d.code === 0) {
                        stop();
                        var s = parseSessionUrl(d.url || "");
                        if (s) {
                            gen++;
                            var hadW = Accounts.count();
                            var wa = Accounts.remember(s, {}, intoId);
                            onState({ kind: "done", via: "web", mid: 0,
                                      accId: wa && wa.id,
                                      created: Accounts.count() > hadW,
                                      into: intoId });
                            return;
                        }

                        /* No credentials in the query: this is the ticket flow,
                         * where the cookies exist only as Set-Cookie on the
                         * cross-domain hop. Fetch it and let the engine's jar
                         * take them — this code never gets to see them. */
                        onState({ kind: "finishing" });
                        /* Empty the jar first so what lands is unambiguously
                         * this account and jar ownership is true. */
                        Accounts.clearJar();

                        var hop = new XMLHttpRequest();
                        hop.open("GET", d.url, true);
                        try { hop.withCredentials = true; } catch (e) {}
                        hop.onreadystatechange = function () {
                            if (hop.readyState !== 4) { return; }
                            if (mine !== gen) { return; }
                            /* Storing an account for a hop that failed left
                             * isLoggedIn permanently true with nothing behind
                             * it. */
                            if (hop.status < 200 || hop.status >= 400) {
                                onState({ kind: "error", why: "换取凭证失败 HTTP " + hop.status });
                                return;
                            }
                            gen++;
                            var hadJ = Accounts.count();
                            var ja = Accounts.remember(
                                { viaCookieJar: true, savedAt: new Date().getTime() },
                                {}, intoId);
                            onState({ kind: "done", via: "web", mid: 0,
                                      accId: ja && ja.id,
                                      created: Accounts.count() > hadJ,
                                      into: intoId });
                        };
                        hop.onerror = function () {
                            if (mine !== gen) { return; }
                            onState({ kind: "error", why: "跨域换取凭证失败" });
                        };
                        hop.send();
                        return;
                    }
                    if (d.code === 86038) { stop(); onState({ kind: "expired" }); return; }
                    if (d.code === 86090 && announced !== 86090) {
                        announced = 86090;
                        onState({ kind: "scanned" });
                    }
                }, function () { /* a dropped poll is not fatal */ });
            }, 3000);
        }, function (why) { onState({ kind: "error", why: why }); });
    }

    function parseSessionUrl(url) {
        var out = {}, qs = String(url || "");
        var q = qs.indexOf("?");
        qs = q >= 0 ? qs.slice(q + 1) : qs;
        var pairs = qs.split("&");
        for (var i = 0; i < pairs.length; i++) {
            /* Split on the first = only: SESSDATA and gourl both carry further
             * = characters in their values, and requiring exactly two parts
             * silently dropped the session. */
            var eq = pairs[i].indexOf("=");
            if (eq <= 0) { continue; }
            out[pairs[i].slice(0, eq)] = decodeURIComponent(pairs[i].slice(eq + 1));
        }
        if (!out.SESSDATA) { return null; }
        return {
            SESSDATA: out.SESSDATA,
            bili_jct: out.bili_jct || "",
            DedeUserID: out.DedeUserID || "",
            savedAt: new Date().getTime()
        };
    }

    return {
        session: session,

        /* An account whose credentials only ever lived in the jar, after the jar
         * has moved on, is not signed in however much is stored about it —
         * reporting otherwise would serve a signed-out feed under their name. */
        isLoggedIn: function () {
            var acc = Accounts.active();
            return !!(acc && acc.session && !Accounts.needsRelogin(acc));
        },

        /* True when the cookies live in the engine jar and this code cannot read
         * them: AVPlay takes no jar, so playback has to go through MSE. */
        needsJar: function () {
            var s = session();
            return !!(s && !s.SESSDATA);
        },

        /* Only when this account is the one the jar holds. Letting a request set
         * withCredentials otherwise would attach whichever account last logged
         * in through the web flow. */
        jarIsOurs: function () {
            var acc = Accounts.active();
            return !!(acc && Accounts.jarBelongsTo(acc.id));
        },

        cookieHeader: function () {
            var acc = Accounts.active();
            var s = acc && acc.session;
            if (!s || !s.SESSDATA) { return ""; }
            var parts = ["SESSDATA=" + s.SESSDATA];
            if (s.bili_jct) { parts.push("bili_jct=" + s.bili_jct); }
            if (s.DedeUserID) { parts.push("DedeUserID=" + s.DedeUserID); }
            /* Stable per account, so this client does not look like a new device
             * on every request. */
            if (acc.buvid) { parts.push("buvid3=" + acc.buvid); }
            return parts.join("; ");
        },

        /* The CSRF token for cookie-style writes. The web flow never exposes
         * one; TV accounts use their APP token for explicit video actions. */
        csrf: function () {
            var s = session();
            return (s && s.bili_jct) || "";
        },

        /* The other way to sign a write. The TV login hands back an access token
         * as well as cookies, and the app-style endpoints take it in the body —
         * no CSRF token, no Origin, no jar. On a device whose requests carry
         * neither an Origin a website would recognise nor a browser's full set
         * of cookies, that is the path that fits. */
        accessKey: function () {
            var s = session();
            return (s && s.access_token) || "";
        },

        signTv: function (params) { return sign(params); },

        /* Signs the active account out and forgets it entirely, along with the
         * watch history that belonged to them. */
        logout: function () {
            var acc = Accounts.active();
            if (acc) { Accounts.remove(acc.id); }
        },

        /* onState is called with one of:
         *   {kind:"qr", url, via}   show this to the user
         *   {kind:"scanned"}        phone has it, awaiting confirmation
         *   {kind:"finishing"}      web fallback exchanging the ticket
         *   {kind:"done", via}      account stored and made active
         *   {kind:"expired"}        need a fresh code
         *   {kind:"error", why}
         *
         * The TV flow is tried first because it is the only one that yields
         * credentials this code can store. The fallback happens before any QR
         * reaches the screen — swapping the code out from under someone who is
         * already pointing a phone at it would be worse than failing. */
        startLogin: function (onState, restoreId) {
            this.cancelLogin();
            intoId = restoreId || null;
            var mine = gen;
            startTv(mine, onState, function (why) {
                if (mine !== gen) { return; }
                onState({ kind: "fallback", why: why });
                startWeb(mine, onState);
            });
        },

        cancelLogin: function () { gen++; stop(); intoId = null; }
    };
})();

files.js/resume.js:
/* Where each video was left off.
 *
 * Kept locally *as well as* pushed to bilibili's history — see `API.report`.
 * The local copy is not redundant: it is instant, which is what makes the
 * progress slivers appear with the cards rather than a request later; it knows
 * about the last thirty seconds, which the report interval does not; it works
 * for accounts added through the web fallback, which have no CSRF token to
 * write with; and it survives a failed request.
 *
 * The television is shared, so this is stored per account — nobody wants their
 * half-watched videos showing up under somebody else's name, and a resume point
 * from another person is worse than none at all. The namespace is re-derived on
 * every access rather than captured once: an account switch that happened
 * between two calls then repairs itself, and the data still in memory is written
 * back to the person it belongs to before the new namespace is read.
 */
var Resume = (function () {
    "use strict";

    var KEY = "bili.resume";
    var LIMIT = 300;          /* entries; a TV that runs for months should not grow forever */
    var MIN_SECONDS = 30;     /* below this there is nothing worth resuming */
    var END_MARGIN = 30;      /* treat the last half minute as finished */

    var map = null;
    var mapKey = null;        /* the namespace `map` was read from */
    var dirty = false;

    /* Videos bilibili itself says are gone — playurl and view both answer
     * `-404 啥都木有`, which is what a takedown looks like from here. Reuploads
     * of films and shows are removed constantly while the card that opens them
     * lives on in a feed, in the account's history and in this television's own
     * 继续观看 row.
     *
     * Device level on purpose — the raw key, not `Accounts.scope()`. A takedown
     * is a fact about the video, not about the viewer, so one person meeting it
     * spares everyone else on this television the same dead card.
     *
     * It hides the card from 继续观看 and does nothing else. The watch record
     * stays: 我的 answers 「这台电视放过什么」, and something watched and later
     * deleted is still part of that answer — and deleting entries outright is a
     * mistake this file has already made twice, in `record()` and in the call
     * that became `finished()`, both of which quietly emptied 我的.
     *
     * Marks expire, and playing the video clears one. A -404 is usually a
     * takedown, but 审核中 answers identically and comes back a day later; a
     * mark with no end would hide such a video from the row for good, on
     * evidence that had stopped being true. */
    var DEAD_KEY = "bili.dead.v1";
    var DEAD_TTL = 7 * 24 * 3600 * 1000;
    var DEAD_CAP = 200;

    function writeDead(m) {
        var keys = [], k;
        for (k in m) { if (m.hasOwnProperty(k)) { keys.push(k); } }
        keys.sort(function (a, b) { return (m[a] || 0) - (m[b] || 0); });
        while (keys.length > DEAD_CAP) { delete m[keys.shift()]; }
        try { localStorage.setItem(DEAD_KEY, JSON.stringify(m)); } catch (e) {}
    }

    function readDead() {
        var m;
        try { m = JSON.parse(localStorage.getItem(DEAD_KEY) || "{}"); }
        catch (e) { m = {}; }
        var now = new Date().getTime(), expired = false, k;
        for (k in m) {
            if (!m.hasOwnProperty(k)) { continue; }
            if (now - (m[k] || 0) > DEAD_TTL) { delete m[k]; expired = true; }
        }
        if (expired) { writeDead(m); }
        return m;
    }

    /* Turning the television off is the normal way to stop watching, and it
     * gives no unload event worth trusting, so writes are flushed on a timer
     * rather than only when playback ends. */
    setInterval(function () { flushNow(); }, 10000);

    function trim(m) {
        var keys = [];
        for (var k in m) { if (m.hasOwnProperty(k)) { keys.push(k); } }
        if (keys.length <= LIMIT) { return; }
        keys.sort(function (a, b) { return (m[b].at || 0) - (m[a].at || 0); });
        for (var i = LIMIT; i < keys.length; i++) { delete m[keys[i]]; }
    }

    function writeTo(k, m) {
        if (!k) { return; }
        trim(m);
        try { localStorage.setItem(k, JSON.stringify(m)); } catch (e) {}
    }

    function load() {
        var k = Accounts.scope(KEY);
        if (map && mapKey === k) { return map; }

        /* Somebody else is watching now. What has not been written yet belongs
         * to the person who was. */
        if (map && dirty) { writeTo(mapKey, map); }
        dirty = false;
        mapKey = k;
        try { map = JSON.parse(localStorage.getItem(k) || "{}"); }
        catch (e) { map = {}; }
        return map;
    }

    function flush() { flushNow(); }

    function flushNow() {
        /* load() writes the previous account's entries out itself if the
         * namespace moved, and clears the flag when it does. */
        var m = load();
        if (!dirty) { return; }
        dirty = false;
        writeTo(mapKey, m);
    }

    function id(bvid, cid) { return bvid + ":" + cid; }

    /* When this person last emptied their history on this set (设置 → 清空观看
     * 记录, 2026-10-18). Per account, like the list it empties. */
    var CLEARED_KEY = "bili.historyClearedAt.v1";

    return {
        /* Empties this account's list on this set and remembers when. Only the
         * local list is deleted: the account's server history is the same one
         * the phone and the website read, and wiping that is not what a viewer
         * tidying the television asked for. app.js hides server entries older
         * than clearedAt() instead, so 继续观看 and 我的 come up empty until
         * something new is watched. */
        clearAll: function () {
            var m = load();
            for (var k in m) { if (m.hasOwnProperty(k)) { delete m[k]; } }
            dirty = false;
            writeTo(mapKey, m);
            try { localStorage.setItem(Accounts.scope(CLEARED_KEY), String(new Date().getTime())); } catch (e) {}
        },
        clearedAt: function () {
            var v = 0;
            try { v = Number(localStorage.getItem(Accounts.scope(CLEARED_KEY)) || 0); } catch (e) {}
            return v || 0;
        },

        /* Called on every time update, so it only touches storage now and then. */
        record: function (bvid, cid, positionMs, durationMs, card) {
            if (!bvid || !positionMs) { return; }
            var pos = positionMs / 1000, dur = (durationMs || 0) / 1000;
            var m = load();
            var key = id(bvid, cid);

            var prev = m[key] || {};

            /* Too early to be worth resuming, or close enough to the end to
             * count as finished. Either way there is no position to keep — but
             * it was still watched, and this list is the only record of what
             * this television played. Deleting the entry outright meant a video
             * opened and left after a minute never appeared in 我的 at all, and
             * so did one watched all the way through. */
            var atEnd = !!(dur && pos > dur - END_MARGIN);
            var resumable = pos >= MIN_SECONDS && !atEnd;

            m[key] = {
                pos: resumable ? Math.floor(pos) : 0,
                /* "Finished" used to be written as pos 0, the same as "barely
                 * started", and a just-finished video then sat at the top of
                 * 继续观看 by recency until the server history caught up —
                 * never, for a web-fallback account that cannot report -1. */
                done: atEnd,
                dur: Math.floor(dur),
                at: new Date().getTime(),
                card: card || prev.card    /* enough to redraw it in 我的 */
            };
            dirty = true;
        },

        flush: flush,

        positionMs: function (bvid, cid) {
            var e = load()[id(bvid, cid)];
            return e ? e.pos * 1000 : 0;
        },

        /* Which part of a multi-part upload was watched last, and where it was
         * left. Without this, opening a series from the feed or from 我的 always
         * restarted at P1 — the position for the part you were actually on was
         * stored all along, but nothing ever asked which part that was. */
        lastPart: function (bvid) {
            var m = load(), best = null, bestAt = -1, prefix = bvid + ":";
            for (var k in m) {
                if (!m.hasOwnProperty(k)) { continue; }
                if (k.indexOf(prefix) !== 0) { continue; }
                var at = m[k].at || 0;
                if (at <= bestAt) { continue; }
                bestAt = at;
                best = {
                    cid: Number(k.slice(prefix.length)) || 0,
                    positionMs: (m[k].pos || 0) * 1000,
                    page: (m[k].card && m[k].card.page) || 0,
                    part: (m[k].card && m[k].card.part) || ""
                };
            }
            return best;
        },

        /* 0..1 for the sliver drawn across a card's thumbnail.
         * Feeds carry no cid — search, 动态 and history never have one — so the
         * marker matches on the video and takes its furthest part. Keying on
         * bvid:cid meant the sliver silently never appeared on exactly the
         * screens where "where did I get to" matters most. */
        fraction: function (bvid) {
            /* The most recently touched part speaks for the video. "Any part
             * done → 1" dropped a 24-part series from 继续观看 the moment one
             * episode ended, with the next one half-watched; "max over parts"
             * has the mirror problem. Where the viewer got to is the part
             * they were last on. */
            var m = load(), latest = null;
            for (var k in m) {
                if (!m.hasOwnProperty(k)) { continue; }
                if (k.indexOf(bvid + ":") !== 0) { continue; }
                var e = m[k];
                /* `>=`: two parts written in the same millisecond (finish P3,
                 * start P4) keep insertion order, and the later one wins. */
                if (!latest || (e.at || 0) >= (latest.at || 0)) { latest = e; }
            }
            if (!latest) { return 0; }
            if (latest.done) { return 1; }
            return latest.dur ? Math.min(1, latest.pos / latest.dur) : 0;
        },

        /* Most-recent-first, for the 我的 screen.
         *
         * The server-side history is now written too — accounts added through
         * the TV login carry the CSRF token that needs — but this list stays,
         * and stays first: it is instant, it survives a failed request, and it
         * knows about the last thirty seconds, which the server does not.
         *
         * Each card is copied and stamped with `at`. Copied because the caller
         * merges these with the server's cards and writes to the winner, and
         * the originals here are what gets persisted; stamped because a merged
         * list has to sort by time and a card alone carries none. */
        recent: function (limit) {
            var m = load(), seen = {}, out = [];
            var keys = [];
            for (var k in m) { if (m.hasOwnProperty(k)) { keys.push(k); } }
            keys.sort(function (a, b) { return (m[b].at || 0) - (m[a].at || 0); });
            for (var i = 0; i < keys.length && out.length < (limit || 24); i++) {
                var e = m[keys[i]];
                if (!e.card) { continue; }
                if (seen[e.card.bvid]) { continue; }
                seen[e.card.bvid] = 1;
                var copy = {};
                for (var f in e.card) {
                    if (e.card.hasOwnProperty(f)) { copy[f] = e.card[f]; }
                }
                copy.at = e.at || 0;
                out.push(copy);
            }
            return out;
        },

        /* Watched to the end: there is nothing left to resume, but it belongs in
         * the history more than anything else does. This used to delete the
         * entry, which quietly removed finished videos from 我的. */
        finished: function (bvid, cid) {
            var m = load(), e = m[id(bvid, cid)];
            if (!e) { return; }
            e.pos = 0;
            e.done = true;
            e.at = new Date().getTime();
            dirty = true;
            flush();
        },

        /* bilibili answered -404 for this video: it is gone, and no amount of
         * pressing play will change that. */
        markDead: function (bvid) {
            if (!bvid) { return; }
            var m = readDead();
            m[bvid] = new Date().getTime();
            writeDead(m);
        },

        /* It played — so whatever the -404 was, it is over. Self-correction
         * costs one read in the common case and writes nothing. */
        markAlive: function (bvid) {
            if (!bvid) { return; }
            var m = readDead();
            if (!m[bvid]) { return; }
            delete m[bvid];
            writeDead(m);
        },

        /* The whole set at once, pruned. Callers filter a list against it, and
         * asking per card would re-read and re-parse storage for every card on
         * the screen. */
        dead: readDead
    };
})();

