    var rank352 = false;   /* selftest: the web ranking answers -352 */

    function buvid3(done) {
        if (buvidKnown !== null) { done(buvidKnown); return; }
        if (buvidWaiting) { buvidWaiting.push(done); return; }
        buvidWaiting = [done];
