                    ? Auth.signTv({ access_key: key, vmid: mid, pn: page, ps: 50 })
                    : query);
                getJson(url, function (d) { deliver(d, true); }, function () {
                    /* The public app route is still useful if a TV token is
                     * rejected by this older endpoint. */
