        enterHold = null;
        clearTimeout(hold.timer);
        e.preventDefault();
        if (hold.fired || current !== hold.target) { return; }
        if (new Date().getTime() - hold.started >= LONG_ENTER_MS) {
            hold.target.onlongselect();
        } else if (hold.target.onselect) {
