    var badHosts = {};
    /* Which video the blacklist belongs to. reset() must NOT clear it: the
     * in-place restart goes through Player.playDash → reset(), and clearing
     * there wiped the list mid-incident — 19:52 on 2026-08-03 the same cosov
     * had to be re-learned with a fresh 403 on every restart of the same
     * video. The list turns over when the *video* changes, detected from the
     * cid baked into the stream url path. */
    var badHostsScope = "";
    /* Files (representations), same scope and turnover as badHosts. A 403 is
     * usually aimed at one *file*, not one host — 2026-08-06 15:54: a video
     * whose hev1-720p file answered 403 everywhere while its 1080p sibling
     * played fine. Host-level blacklisting cannot express that. */
    var badFiles = {};

    /* Per-video lessons, persisted device-level and expiring. Re-entering a
     * sick video used to re-learn everything from scratch: on 08-09 the same
     * three starved files cost the same watchdog rounds on every entry — 40
     * seconds to a picture the previous entry had already found at av01.
     * The lesson (winning family, bad hosts, bad files, failed route) is
     * keyed by cid and expires after six hours: per-file weather flips
     * between evenings — 08-06 av01 was the disease and H.265 the cure,
     * 08-09 the exact mirror — so yesterday's lesson is not a fact, it is a
     * lie. That TTL is the design, not a nicety. */
    var LESSON_KEY = "bili.lessons.v1";
    var LESSON_TTL = 6 * 3600 * 1000;
    var LESSON_CAP = 100;
    var lessonFamily = "";   /* soft first-choice for the current video */
    var lastSegReq = null;   /* last segment response, measured against itself */
    var lastAskedRange = ""; /* only for responses that carry no content-range */

    /* Counts, not pairs. The question at a stall is whether the player is still
     * asking for bytes, and pairing requests to responses is what this file has
     * already got wrong once today — two counters and two timestamps answer it
     * with nothing to mismatch:
     *
     *   发出 == 回来, 最后一次发出在 12 秒前  → Shaka stopped asking. Nothing is
     *       hanging; the fault is on this side (the buffer logic, the index, the
     *       element) and tearing down to rebuild is the right response.
     *   发出 > 回来, 最后一次回来在 12 秒前   → a request went out and nothing came
     *       back. The connection is hanging, or the CDN is sitting on it — and the
     *       eight-way probe fired in the same breath says which.
     *
     * Those two want opposite fixes (rebuild at once vs back off and wait), and
     * this session has been arguing between them without the one measurement
     * that separates them. */
    var segStarted = 0, segFinished = 0, segLastStart = 0, segLastFinish = 0;

    /* Reset per session, or 「在飞」 is a lie that only ever grows. Every seek and
     * every adaptation switch aborts requests that are already out, and an
     * aborted request increments 发出 and never increments 回来 — so without
     * this, a viewer who scrubs three times gets 「在飞=7」 reported at the next
     * stall with nothing actually in flight, which reads as exactly the
     * diagnosis it is not. Caught in review the same evening the counter was
     * added, and it matters more than usual because this number is the evidence
     * behind the connectionTimeout change: the 08-15 18:31 sample survives it
     * (6→7→7→7 across three rebuilds, not 6→12→18, so those were the same hung
     * requests rather than accumulated debris) but that was luck, not design. */
    function resetSegTraffic() {
        segStarted = 0; segFinished = 0; segLastStart = 0; segLastFinish = 0;
        /* The evidence line too: at a first-load stall it otherwise describes
         * the previous video's last range as 「完整」, pointing the reader at
         * the decoder for a stall that never received a byte. */
        lastSegReq = null; lastAskedRange = "";
    }

    function segTraffic() {
        var now = new Date().getTime();
        return "分段请求 发出=" + segStarted + " 回来=" + segFinished +
               " 在飞=" + Math.max(0, segStarted - segFinished) +
               " 最后一次发出=" + (segLastStart ? ((now - segLastStart) / 1000).toFixed(1) + "s前" : "无") +
               " 最后一次回来=" + (segLastFinish ? ((now - segLastFinish) / 1000).toFixed(1) + "s前" : "无");
    }

    function readLessons() {
        var now = new Date().getTime(), keep = {}, k;
        try {
            var all = JSON.parse(localStorage.getItem(LESSON_KEY) || "{}");
            for (k in all) {
                if (all[k] && now - (all[k].t || 0) < LESSON_TTL) { keep[k] = all[k]; }
            }
        } catch (e) {}
        return keep;
    }

    function writeLessons(map) {
        var keys = [], k;
        for (k in map) { keys.push(k); }
        keys.sort(function (a, b) { return (map[a].t || 0) - (map[b].t || 0); });
        while (keys.length > LESSON_CAP) { delete map[keys.shift()]; }
        try { localStorage.setItem(LESSON_KEY, JSON.stringify(map)); } catch (e) {}
    }

    function objectKeys(o) { var out = [], k; for (k in o) { out.push(k); } return out; }

    /* Raise the "try the app endpoint's strong token" request, once per video,
     * when a web manifest has met a 403 this video. Returns true if it fired —
     * the caller must then stop (not drop a tier). app.js turns the error into a
     * playurlDashStrong call; its result comes back as a fresh manifest whose
     * `strong` flag stops this from firing again. A strong manifest drops tiers
     * as before.
     *
     * `known403` is the load-failure path passing its own 403 directly:
     * playDashWithShaka's catch never calls noteBadFile, so badFiles stays empty
     * there and the badFiles-only guard was a permanent no-op — which for a
     * reupload that 403s at load time (the headline target) meant the strong
     * token fired only after the whole family+tier ladder had flooded the
     * limiter. Either signal — a recorded bad file, or a 403 in hand — is
     * enough. */
    function offerStrongToken(known403) {
        if (strongEmitted) { return false; }
        /* `lastDash.dash.strong` — the flag lives on the playurl payload; the
         * old `lastDash.strong` read an undefined property and never fired. */
        if (lastDash && lastDash.dash && lastDash.dash.strong) { return false; }
        if (!known403 && !saw403) { return false; }
        strongEmitted = true;
        /* Once per *manifest object*, and remembered on the object: when the
         * strong fetch fails and app.js hands this very web manifest back to
         * walk the tier ladder, the re-arm below must not fire again for it —
         * it did, and the ladder's exit 「回到 web 端点压中低档」 never dropped
         * a tier, it re-asked for a strong token that had just failed. */
        if (lastDash && lastDash.dash) { lastDash.dash.strongTried = true; }
        log("web 令牌高档被 403 拒，压档前先试 app 端点强令牌");
        lastDecodeHandled = false;
        emit("error", "web 令牌 403，交给 app 端点强令牌");
        return true;
    }

    function stashLessonFor(scope, patch) {
        if (!scope) { return; }
        var map = readLessons();
        var l = map[scope] || {};
        if (scope === badHostsScope) {
            l.bh = objectKeys(badHosts);
            l.bf = objectKeys(badFiles);
        }
        if (patch && patch.f) { l.f = patch.f; }
        if (patch && patch.r) { l.r = patch.r; }
        /* `in`, not truthiness: writing 0 is how a lesson is withdrawn. */
        if (patch && ("s" in patch)) { l.s = patch.s; }
        l.t = new Date().getTime();
        map[scope] = l;
        writeLessons(map);
    }

    /* Snapshot what the current video has taught us — called from the same
     * places the in-memory maps learn, so store and session cannot drift. */
    function stashLesson(patch) { stashLessonFor(badHostsScope, patch); }

    function hostOf(u) { return String(u || "").split("/")[2] || ""; }

    function scopeOf(dash) {
        var v = dash && dash.video && dash.video[0];
        var u = (v && (v.baseUrl || (v.urls && v.urls[0]))) || "";
        var m = /upgcxcode\/\d+\/\d+\/(\d+)\//.exec(String(u));
        return m ? m[1] : String(u).split("?")[0];
    }

    /* Returns whether this call taught us something new. The immediate-rebuild
     * below keys on that, and nothing else bounds it: the once-per-session
     * flag it used at first was declared inside playDashWithShaka, so every
     * rebuild arrived with a fresh flag and a video whose files 403 on every
     * host rebuilt itself three times a second, forever — a spinner from the
     * sofa, hundreds of identical lines in the collector. */
    function noteBadHost(err) {
        if (!err || err.code !== 1001 || !err.data) { return false; }
        var status = err.data[1];
        if (status !== 403 && status !== 401) { return false; }
        saw403 = true;
        var h = hostOf(err.data[0]);
        if (h && !badHosts[h]) {
            badHosts[h] = true;
            log("镜像 " + h + " 返回 " + status + "，这个视频内不再排在前面");
            stashLesson(null);
            return true;
        }
        return false;
    }

    function fileTokenOf(u) {
        var path = String(u || "").split(/[?#]/)[0];
        var seg = path.split("/").pop();
        return /\.m4s$/.test(seg) ? seg : "";
    }

    /* Whether a file token names one of this manifest's *video* representations.
     *
     * lastSegReq records whichever stream asked last, and audio asks too. On
     * 2026-08-11 20:52 the parse-failure rung took that token at face value and
     * blacklisted the soundtrack: both audio representations were dropped within
     * twenty seconds, the manifest lost its audio, and the attempt still ended in
     * 有声退出 — the rung made the failure worse than the one it was added to
     * fix. Dropping a video tier leaves other tiers; dropping the audio leaves
     * nothing to play. */
    function isVideoToken(dash, tok) {
        var list = (dash && dash.video) || [];
        for (var i = 0; i < list.length; i++) {
            var u = (list[i].urls && list[i].urls[0]) || list[i].baseUrl;
            if (fileTokenOf(u) === tok) { return true; }
        }
        return false;
    }

    /* Same contract as noteBadHost: returns the newly learned file token, or
     * "" — and *newly learned* is what bounds the rebuild below, exactly the
     * lesson the host blacklist paid for. N poisoned files cost at most N
     * rebuilds per video. */
    function noteBadFile(err) {
        if (!err || err.code !== 1001 || !err.data) { return ""; }
        var status = err.data[1];
        if (status !== 403 && status !== 401) { return ""; }
        saw403 = true;
        var tok = fileTokenOf(err.data[0]);
        if (!tok || badFiles[tok]) { return ""; }
        /* Only what droppable() says can be left out. Recording an undroppable token
         * is a silent side effect: the entry does nothing except pollute the
         * lesson and make the next 403 on the same file unrecognisable as new —
         * 2026-08-11 20:52, the last remaining audio file was learned this way
         * and its second 403 fell straight through to the critical-retry exit.
         *
         * Droppable means: a video representation, or an audio representation
         * with a sibling left to carry the sound. The CDN discriminates
         * per-file on audio too (21:07: akam refused 30232 while cosov refused
         * 30280, and 30216 was healthy the whole time) — refusing to ever drop
         * audio just walks the refused file into the same exit via the retry
         * counter. The last audio file standing is the mirror-rotation rung's
         * job — see the caller. */
        if (lastDash && !isVideoToken(lastDash.dash, tok)) {
            var alist = (lastDash.dash && lastDash.dash.audio) || [];
            var mine = false;
            for (var ai = 0; ai < alist.length; ai++) {
                if (repToken(alist[ai]) === tok) { mine = true; break; }
            }
            if (!mine || unbannedSiblings(alist, tok) < 1) { return ""; }
        }
        badFiles[tok] = new Date().getTime();
        stashLesson(null);
        return tok;
    }

    /* One rotation per audio file per video: enough to reach the other mirror,
     * bounded so two hosts refusing the same file cannot spin a rebuild loop. */
    var audioRotated = {};

    /* Per video: has the "web token 403 → try the app endpoint's strong token"
     * request been raised yet. Raised once, before the first tier drop — the
     * app endpoint mints a token the CDN accepts where the web endpoint's is
     * refused, so restoring 1080p beats degrading to 480p. Reset per video with
     * the rest of the per-video state below. */
    var strongEmitted = false;
    /* Whether this video has actually met a 403/401. `badFiles` is not that:
     * the decode ladder fills it for parse failures and the lesson replay
     * pre-fills it on entry, and the strong-token rung used to fire on either
     * — logging a 403 nobody received and spending the aid+strong+sidx round
     * trip ahead of the avc1 fallback. Reset with the per-video scope. */
    var saw403 = false;

    /* B (2026-10-20): a web-token 403 in the middle of playback no longer tears
     * the player down. 10-20 15:23: refused eleven seconds in, with 30-odd
     * seconds already buffered, the rebuild froze the picture for seven
     * seconds. The strong token names the same files (same path), so app.js
     * mints one in the background while the buffer plays on, and the request
     * filter in ensureShaka rewrites every later segment request for a file it
     * knows to the strong url. `tokenSwap` is that path → urls map, per video;
     * `swapPending` is when the mint was asked for, 0 when none is. */
    var tokenSwap = null, swapPending = 0, swapGen = 0, swapQuiet = 0, tokenSwapFor = null;
    /* deploy.sh --tokenswap: spoil the next media request's signature so the
     * CDN answers a real 403 — a refusal cannot be ordered up otherwise. */
    var fake403 = 0;
    /* The same, for a refusal on the second host after the first one failed —
     * and, for that check, a session that cannot mint (no account). */
    var fakeFailover = 0, fakeNoMint = false, failoverRefusals = 0;
    function swapPathOf(u) { return String(u || "").replace(/^[a-z]+:\/\/[^\/]+/i, "").split(/[?#]/)[0]; }

    /* Only once there is a picture on a web manifest, and only the first time:
     * at load time there is nothing to keep playing (that 403 goes through
     * load()'s own catch), and a second refusal after a swap is a different
     * problem for the ladder. */
    function canSwapToken() {
        return mode === "mse" && !!shakaPlayer && !loadPending && haveTime &&
               !!lastDash && !!lastDash.dash && !lastDash.dash.strong &&
               !lastDash.dash.strongTried && !strongEmitted;
    }

    /* Whether app.js could mint a strong token for this session at all — what
     * its tokenSwap handler asks. Without an access_key the swap is declined
     * on the spot, and what that falls back to is the teardown. */
    function strongMintable() {
        if (fakeNoMint) { return false; }
        return typeof Auth !== "undefined" && Auth.isLoggedIn() && !!Auth.accessKey();
    }

    /* A 403 from a host that was not first in its file's list is that host
     * refusing this token — not the file, not the lead: Shaka moves on to the
     * next BaseURL only after a *recoverable* failure on the one before (4.12's
     * NetworkingEngine; a 401/403 is critical and never moves on). 10-29, two
     * sets on no account, akam serving the web token: a cut on akam, the retry
     * on cosov, its 403 — and the ladder took it for the token (a swap that
     * cannot happen without an access_key, a teardown, then the progressive
     * file akam had refused at the start: out, five minutes in) or for the
     * file (480p and 360p excised in turn on a cosov 403 each, the list emptied
     * twice: out, while the probe read 206 from akam for that same file). The
     * pair goes on the manifest — the token is the manifest's, so a refetch or
     * the strong one starts clean — the request filter leaves it out, and the
     * stream goes on from the lead. At most files × hosts. When the lead has
     * refused the file too, this is the ordinary 403 below. Only with a
     * picture up: a load's 403 is load()'s catch's, whose immediate rebuild
     * keys on noteBadHost learning the host *there*. */
    function refusedOnFailover(err) {
        var u = err.data && err.data[0], dash = lastDash && lastDash.dash;
        var h = hostOf(u), tok = fileTokenOf(u);
        if (!h || !tok || !dash || loadPending || !haveTime) { return false; }
        var reps = [].concat(dash.video || [], dash.audio || []), lead = "";
        for (var i = 0; i < reps.length; i++) {
            if (repToken(reps[i]) === tok) { lead = hostOf((reps[i].urls && reps[i].urls[0]) || reps[i].baseUrl); break; }
        }
        var refused = dash.refused || (dash.refused = {});
        if (!lead || lead === h || refused[lead + " " + tok]) { return false; }
        if (!refused[h + " " + tok]) {
            refused[h + " " + tok] = true;
            failoverRefusals++;
            noteBadHost(err);
            var ahead = 0;
            try { ahead = bufferedAhead(el("html5-video")); } catch (e) {}
            log("文件 " + tok + " 在 " + lead + " 失手后换到 " + h + "，被 " + err.data[1] +
                "：是这台主机不认这个令牌，不怪文件、不换令牌；这个文件不再找它要，接着从 " + lead +
                " 放，前方还有 " + ahead.toFixed(1) + " 秒");
        }
        try { shakaPlayer.retryStreaming(); } catch (e2) {}
        return true;
    }

    function startTokenSwap(err) {
        var g = ++swapGen;
        swapPending = new Date().getTime();
        swapQuiet = 0;
        strongEmitted = true;
        lastDash.dash.strongTried = true;
        var ahead = 0;
        try { ahead = bufferedAhead(el("html5-video")); } catch (e) {}
        log("web 令牌被拒（" + hostOf(err.data && err.data[0]) + " " + (err.data && err.data[1]) +
            "），不拆播放器：后台换强令牌，前方还有 " + ahead.toFixed(1) + " 秒");
        emit("tokenSwap", ahead);
        setTimeout(function () {
            if (swapPending && g === swapGen) { swapFailed("10 秒还没换上"); }
        }, 10000);
    }

    /* Back to the old way: app.js's 403 handler tears down and rebuilds. */
    function swapFailed(why) {
        if (!swapPending) { return; }
        swapPending = 0;
        swapGen++;
        log("后台换令牌没成（" + why + "），改回拆掉重建");
        lastDecodeHandled = false;
        emit("error", "web 令牌 403，交给 app 端点强令牌");
    }

    /* The strong manifest app.js minted. Returns how many of the playing
     * manifest's files it covers, 0 when none (and then nothing changed). */
    function swapToken(sd) {
        if (!swapPending || !lastDash || !lastDash.dash || !shakaPlayer || !sd) { return null; }
        var map = {}, lists = [].concat(sd.video || [], sd.audio || []);
        for (var i = 0; i < lists.length; i++) {
            var urls = (lists[i].urls && lists[i].urls.length) ? lists[i].urls : [lists[i].baseUrl];
            for (var j = 0; j < urls.length; j++) { if (urls[j]) { map[swapPathOf(urls[j])] = urls; } }
        }
        var cur = [].concat(lastDash.dash.video || [], lastDash.dash.audio || []);
        var covered = 0, total = 0, inUse = 0, inUseCovered = 0;
        for (var k = 0; k < cur.length; k++) {
            if (!cur[k].segments) { continue; }
            total++;
            /* What this manifest can ask for: its family's tiers up to the cap
             * (and av01 only to 1080P, as Mpd.build has it), minus the files it
             * dropped, and the audio. Counting tiers it never listed made a cap
             * of 720P read as partial on every refusal (review, 10-20). */
            var curUrl = (cur[k].urls && cur[k].urls[0]) || cur[k].baseUrl;
            var isAudio = (lastDash.dash.audio || []).indexOf(cur[k]) >= 0;
            var cap = lastDash.capId || Settings.qnCap();
            var used = !badFiles[fileTokenOf(curUrl)] && (isAudio ||
                       (String(cur[k].codecs || "").split(".")[0] === lastDash.family &&
                        !(cur[k].id > cap) && !(lastDash.family === "av01" && cur[k].id > 80)));
            if (used) { inUse++; }
            var cu = cur[k].urls || [cur[k].baseUrl];
            for (var m = 0; m < cu.length; m++) {
                if (map[swapPathOf(cu[m])]) { covered++; if (used) { inUseCovered++; } break; }
            }
        }
        /* Every file the manifest can ask for, or none of this: 10-20 16:37 a
         * swap covering 11 of 15 left one tier of the playing family on the web
         * token, ABR stepped onto it, its 403 stopped the video stream without
         * a word, and seventy seconds later the buffer ran dry into a ladder
         * that ended on a frozen av01 picture. A partial swap is handed back
         * (`partial`) and app.js rebuilds on the strong manifest instead. */
        if (!covered || inUseCovered < inUse) {
            return { covered: covered, total: total, partial: inUseCovered < inUse,
                     inUse: inUse, inUseCovered: inUseCovered };
        }
        tokenSwap = map;
        tokenSwapFor = lastDash.dash;
        swapPending = 0;
        swapGen++;
        /* From here the strong manifest is this player's: every rung of the
         * ladder rebuilds from lastDash.dash, and rebuilding from the web one
         * asked for uncovered files under the refused token; its deadline is
         * also the one that matters for expiry now (review, 10-20). */
        lastDash.dash = sd;
        /* The 403 that started this was the token's, not the file's or the
         * host's — the files are being served now, under the other signature. */
        saw403 = false;
        try { shakaPlayer.retryStreaming(); } catch (e) {}
        return { covered: covered, total: total };
    }

    function leadHostOf(dash) {
        var v = dash && dash.video && dash.video[0];
        return hostOf((v && ((v.urls && v.urls[0]) || v.baseUrl)) || "");
    }

    /* Whether a banned file can be left out at all. Never empty a list — a
     * manifest with no audio (or video) cannot be built, and the honest exit
     * path is a better end than 「拼不出播放清单」 on a self-inflicted wound. */
    function repToken(rep) {
        return fileTokenOf((rep.urls && rep.urls[0]) || rep.baseUrl);
    }

    /* Siblings of `tok` in `list` that are not themselves banned — the number
     * of files that would remain if this one went. Counted against the ban
     * list, not the raw length: the session's payload is never spliced any
     * more, so its length says nothing about what the manifest will hold. */
    function unbannedSiblings(list, tok) {
        var n = 0;
        for (var i = 0; i < list.length; i++) {
            var t = repToken(list[i]);
            if (t !== tok && !badFiles[t]) { n++; }
        }
        return n;
    }

    function droppable(dash, tok) {
        var kinds = ["video", "audio"];
        for (var k = 0; k < kinds.length; k++) {
            var list = (dash && dash[kinds[k]]) || [];
            for (var i = 0; i < list.length; i++) {
                if (repToken(list[i]) === tok) { return unbannedSiblings(list, tok) >= 1; }
            }
        }
        return false;
    }

    /* Fresh playurl responses within the same video (deadline expiry, the
     * app-level restart) arrive with the poisoned representations restored;
     * this re-applies what the video already taught us, the way
     * preferGoodHosts does for hosts. */
    var BAD_FILE_TTL = 5 * 60 * 1000;

    /* A shallow copy of the payload with the banned files left out — the
     * session's own `dash` is never touched. It used to be spliced in place,
     * which quietly broke two promises made around it: the 5-minute TTL
     * (an expired entry could not bring its tier back, the representation was
     * gone), and the 「坏文件名单把清单掏空了，这次忽略名单重建」 rung, which
     * cleared the list and rebuilt from the same gutted arrays — logging a
     * restoration that could not happen. Only a fresh playurl ever restored
     * anything. */
    function withoutBadFiles(dash) {
        /* Expiring, because a 403 from this CDN is the weather of the minute:
         * the same file that refuses everything during a cooldown serves at
         * full speed a few minutes later, and a permanent ban costs a tier for
         * the rest of the video. */
        var now = new Date().getTime();
        for (var tok in badFiles) {
            if (badFiles[tok] !== true && now - badFiles[tok] > BAD_FILE_TTL) {
                delete badFiles[tok];
            }
        }
        var out = {};
        for (var key in dash) { if (dash.hasOwnProperty(key)) { out[key] = dash[key]; } }
        var kinds = ["video", "audio"];
        for (var k = 0; k < kinds.length; k++) {
            var list = dash[kinds[k]] || [], kept = [];
            for (var i = 0; i < list.length; i++) {
                var u = (list[i].urls && list[i].urls[0]) || list[i].baseUrl;
                if (!badFiles[fileTokenOf(u)]) { kept.push(list[i]); }
            }
            if (!kept.length && list.length) {
                log("坏文件名单会把" + (kinds[k] === "video" ? "视频" : "音频") +
                    "列表清空，这一类忽略名单");
            }
            out[kinds[k]] = (kept.length || !list.length) ? kept : list;
        }
        return out;
    }

    /* Every path into playDashWithShaka runs through this, so a manifest can
     * never lead with a host already known to refuse — including the in-place
     * restart, which reuses a session object earlier rotations may have left
