            else if (st.downloaded) { line = "新版本 " + st.downloaded + " 已下载，下次打开应用时生效"; }
            else if (!st.lastCheck) { line = ""; }
            else if (st.lastError) { line = "这次没查成，稍后会自动再试"; }
            else if (st.reinstall) { line = "有新版本，需要重新安装"; }
            else { line = "已是最新版本"; }
