        }],
        ["确认键打开删除确认框", 700, function () {
            if (!onAccounts()) { return null; }
            key(KEY.ENTER);
            return null;
        }],
        ["确认框出现，焦点停在取消上", 600, function () {
            if (!onAccounts()) { return null; }
            if (!count("#screen .acc-confirm")) { return "选中账号后没有出现删除确认框"; }
