        ["按取消，不真的删", 700, function () {
            if (!onAccounts()) { return null; }
            key(KEY.ENTER);
            return null;
        }],
        ["取消之后回到账号列表", 700, function () {
            if (!onAccounts()) { return null; }
            if (count("#screen .acc-confirm")) { return "取消之后确认框还在"; }
